input.command:
$roots = @(
  'C:\Users\KickA\Projects\Active\NeuralShell',
  'C:\Users\KickA\Documents\GitHub\NeuralShell',
  'C:\Users\KickA\Projects',
  'C:\Users\KickA\Documents\GitHub',
  "$env:LOCALAPPDATA\Programs\NeuralShell",
  "$env:LOCALAPPDATA\NeuralShell",
  "$env:APPDATA\neuralshell-v5"
)
foreach ($r in $roots) {
  $exists = Test-Path -LiteralPath $r
  $resolved = if ($exists) { try { (Get-Item -LiteralPath $r).Target; (Resolve-Path -LiteralPath $r).Path } catch { 'ERR' } } else { 'N/A' }
  Write-Output "=== $r === exists=$exists"
  if ($exists -and (Test-Path -LiteralPath (Join-Path $r '.git'))) {
    try { git -C $r rev-parse --show-toplevel 2>$null } catch {}
  }
}

$ErrorActionPreference = 'SilentlyContinue'
$patterns = @(
  'NeuralShell Setup*.exe',
  'app.asar',
  'dist-renderer',
  'index-*.js',
  'index-*.css',
  'release-output',
  'release\final',
  'dist-*',
  'validation-artifacts',
  '*stash*',
  '*extract*'
)
$uiMarkers = @(
  'AdaptiveLayoutEngine',
  'PrimaryWorkspaceRegion',
  'MultiWorkspace',
  'LayoutControlBar',
  'useAdaptiveLayoutChrome',
  'index-CDfqmjqJ'
)
$scanRoots = @(
  'C:\Users\KickA\Projects\Active\NeuralShell',
  'C:\Users\KickA\Documents\GitHub\NeuralShell',
  'C:\Users\KickA\Projects',
  'C:\Users\KickA\Documents\GitHub',
  "$env:LOCALAPPDATA\Programs\NeuralShell",
  "$env:LOCALAPPDATA\NeuralShell",
  "$env:APPDATA\neuralshell-v5"
)
# Collect candidate files
$files = [System.Collections.Generic.List[object]]::new()
$dirs = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)

function Add-File($path) {
  if (-not (Test-Path -LiteralPath $path)) { return }
  try {
    $item = Get-Item -LiteralPath $path -Force
    $resolved = $item.FullName
    try { $resolved = (Resolve-Path -LiteralPath $path).Path } catch {}
    $key = $resolved.ToLower()
    if ($files | Where-Object { $_.ResolvedPath -eq $resolved }) { return }
    $files.Add([PSCustomObject]@{
      ResolvedPath = $resolved
      Name = $item.Name
      Length = $item.Length
      LastWrite = $item.LastWriteTime
      Extension = $item.Extension
    })
  } catch {}
}

function Scan-Dir($root, $depth, $maxDepth) {
  if ($depth -gt $maxDepth) { return }
  if (-not (Test-Path -LiteralPath $root)) { return }
  $name = Split-Path $root -Leaf
  # skip heavy dirs unless NeuralShell-related
  $skip = @('node_modules','.git\objects','.git\lfs','AppData\Local\Temp','Windows')
  foreach ($s in $skip) { if ($root -match [regex]::Escape($s)) { return } }

  try {
    Get-ChildItem -LiteralPath $root -Force -ErrorAction SilentlyContinue | ForEach-Object {
      if ($_.PSIsContainer) {
        $dn = $_.Name
        $interesting = $dn -match 'NeuralShell|neuralshell|dist-renderer|release-output|release|validation-artifacts|stash|worktree|wt-ui|Proof-Final|storefront|deploy_master|_master' -or
          $dn -match '^dist' -or $dn -eq 'final' -or $dn -eq 'win-unpacked'
        if ($interesting -or $depth -lt 2) {
          Scan-Dir $_.FullName ($depth+1) $maxDepth
        }
      } else {
        $n = $_.Name
        $match = $false
        if ($n -like 'NeuralShell Setup*.exe') { $match = $true }
        elseif ($n -eq 'app.asar') { $match = $true }
        elseif ($n -like 'index-*.js' -or $n -like 'index-*.css') { $match = $true }
        elseif ($n -match '^index-[A-Za-z0-9]+\.(js|css)$') { $match = $true }
        if ($match) { Add-File $_.FullName }
      }
    }
  } catch {}
}

# Named dirs
foreach ($root in $scanRoots) {
  if (-not (Test-Path -LiteralPath $root)) { continue }
  Get-ChildItem -LiteralPath $root -Recurse -Directory -Force -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -in @('dist-renderer','release-output','validation-artifacts','win-unpacked','final','stash-extracts','stash_extracts') -or
      $_.Name -like 'dist-*' -or $_.FullName -match 'release[\\/]final' -or $_.FullName -match 'NeuralShell' } |
    Select-Object -First 500 |
    ForEach-Object { $dirs.Add($_.FullName) | Out-Null }
}

# Direct file searches in Projects and GitHub (NeuralShell named only)
$searchBases = @('C:\Users\KickA\Projects','C:\Users\KickA\Documents\GitHub')
foreach ($base in $searchBases) {
  Get-ChildItem -LiteralPath $base -Recurse -Force -ErrorAction SilentlyContinue |
    Where-Object {
      -not $_.PSIsContainer -and (
        $_.Name -like 'NeuralShell Setup*.exe' -or
        $_.Name -eq 'app.asar' -or
        ($_.Name -like 'index-*.js' -and $_.DirectoryName -match 'dist|renderer|assets') -or
        ($_.Name -like 'index-*.css' -and $_.DirectoryName -match 'dist|renderer|assets')
      ) -and $_.FullName -match 'NeuralShell|neuralshell'
    } | ForEach-Object { Add-File $_.FullName }
}

# Scan interesting dirs for index files
foreach ($d in $dirs) {
  Get-ChildItem -LiteralPath $d -Recurse -File -Force -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -like 'index-*.js' -or $_.Name -like 'index-*.css' -or $_.Name -eq 'app.asar' -or $_.Name -like 'NeuralShell Setup*.exe' } |
    ForEach-Object { Add-File $_.FullName }
}

# Installed locations
@("$env:APPDATA\neuralshell-v5") | ForEach-Object {
  if (Test-Path $_) {
    Get-ChildItem $_ -Recurse -File -Force -ErrorAction SilentlyContinue |
      Where-Object { $_.Name -like 'index-*.js' -or $_.Name -like 'index-*.css' -or $_.Name -eq 'app.asar' } |
      ForEach-Object { Add-File $_.FullName }
  }
}

Write-Output "Found $($files.Count) candidate files"
$files | Sort-Object LastWrite -Descending | Select-Object -First 80 | Format-Table Name, Length, LastWrite, @{N='Dir';E={Split-Path $_.ResolvedPath -Parent}} -AutoSize | Out-String -Width 300

$cutoff = Get-Date '2026-05-02'
$uiMarkers = @('AdaptiveLayoutEngine','PrimaryWorkspaceRegion','MultiWorkspace','LayoutControlBar','useAdaptiveLayoutChrome')
$searchBases = @(
  'C:\Users\KickA\Projects',
  'C:\Users\KickA\Documents\GitHub',
  "$env:APPDATA\neuralshell-v5"
)
$candidates = @()
foreach ($base in $searchBases) {
  if (-not (Test-Path $base)) { continue }
  Get-ChildItem -LiteralPath $base -Recurse -File -Force -ErrorAction SilentlyContinue |
    Where-Object {
      $_.FullName -match 'NeuralShell|neuralshell' -and (
        $_.Name -like 'NeuralShell Setup*.exe' -or
        $_.Name -eq 'app.asar' -or
        ($_.Name -match '^index-[A-Za-z0-9_-]+\.js$' -and $_.FullName -match 'dist-renderer|validation-artifacts|release|asar|assets[\\/]index|win-unpacked|stash')
      )
    } | ForEach-Object { $candidates += $_ }
}

# Dedupe by resolved path
$seen = @{}
$unique = @()
foreach ($f in $candidates) {
  try { $rp = (Resolve-Path -LiteralPath $f.FullName).Path } catch { $rp = $f.FullName }
  if ($seen[$rp]) { continue }
  $seen[$rp] = $true
  $unique += [PSCustomObject]@{ Path=$rp; Item=$f }
}
Write-Output "Unique candidates: $($unique.Count)"

function Get-Sha256($path) {
  if ((Get-Item -LiteralPath $path).Length -eq 0) { return 'EMPTY' }
  $h = Get-FileHash -LiteralPath $path -Algorithm SHA256
  return $h.Hash.Substring(0,16)
}

function Test-Markers($path) {
  $found = @()
  try {
    $content = [System.IO.File]::ReadAllText($path)
    foreach ($m in $uiMarkers) { if ($content.Contains($m)) { $found += $m } }
    if ($content -match 'index-CDfqmjqJ|CDfqmjqJ') { $found += 'CDfqmjqJ-ref' }
  } catch {}
  return $found
}

$results = @()
$grouped = $unique | Group-Object { $_.Item.Name }
foreach ($g in ($grouped | Where-Object { $_.Name -match '^(index-|NeuralShell|app\.asar)' })) {
  foreach ($u in $g.Group) {
    $f = $u.Item
    if ($f.Length -eq 0) { continue }
    $hash = Get-Sha256 $f.FullName
    $markers = if ($f.Extension -eq '.js') { Test-Markers $f.FullName } else { @() }
    $results += [PSCustomObject]@{
      Name = $f.Name
      Size = $f.Length
      Date = $f.LastWriteTime
      Hash16 = $hash
      Markers = ($markers -join ',')
      MarkerCount = $markers.Count
      Path = $f.FullName
      AfterMay2 = ($f.LastWriteTime -gt $cutoff)
    }
  }
}

# Dedupe by hash+name
$deduped = $results | Group-Object { "$($_.Name)|$($_.Hash16)" } | ForEach-Object {
  $best = $_.Group | Sort-Object MarkerCount -Descending | Select-Object -First 1
  [PSCustomObject]@{
    Name=$best.Name; Size=$best.Size; Date=$best.Date; Hash16=$best.Hash16
    Markers=$best.Markers; MarkerCount=$best.MarkerCount; AfterMay2=$best.AfterMay2
    Paths = ($_.Group.Path | ForEach-Object { $_ -replace '\\','/' } | Sort-Object -Unique)
    PathCount = ($_.Group.Path | Sort-Object -Unique).Count
  }
}

Write-Output "`n=== INDEX BUNDLES WITH UI MARKERS (deduped by hash) ==="
$deduped | Where-Object { $_.Name -like 'index-*.js' -and $_.MarkerCount -gt 0 } |
  Sort-Object Date -Descending |
  Format-Table Name, Size, Date, MarkerCount, Markers, Hash16, PathCount -AutoSize | Out-String -Width 400

Write-Output "`n=== ALL UNIQUE index-*.js bundles (renderer-related, deduped) ==="
$deduped | Where-Object { $_.Name -like 'index-*.js' -and $_.Size -gt 100000 } |
  Sort-Object Date -Descending |
  Select-Object Name, Size, Date, MarkerCount, Markers, Hash16, PathCount, @{N='SamplePath';E={$_.Paths[0]}} |
  Format-Table -AutoSize | Out-String -Width 400

$cutoff = Get-Date '2026-05-02'
# Installers and asar dedupe
$items = @()
$searchBases = @('C:\Users\KickA\Projects','C:\Users\KickA\Documents\GitHub')
foreach ($base in $searchBases) {
  Get-ChildItem -LiteralPath $base -Recurse -File -Force -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -match 'NeuralShell|neuralshell' -and ($_.Name -like 'NeuralShell Setup*.exe' -or $_.Name -eq 'app.asar') } |
    ForEach-Object { $items += $_ }
}
$seen = @{}
$unique = @()
foreach ($f in $items) {
  try { $rp = (Resolve-Path -LiteralPath $f.FullName).Path } catch { $rp = $f.FullName }
  if ($seen[$rp]) { continue }; $seen[$rp]=$true; $unique += $f
}
Write-Output "Unique installers/asar: $($unique.Count)"
$groups = @{}
foreach ($f in $unique | Where-Object { $_.Length -gt 0 }) {
  Write-Host "Hashing $($f.Name) ($([math]::Round($f.Length/1MB))MB)..." -NoNewline
  $h = (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash
  Write-Host " done"
  $key = "$($f.Name)|$h"
  if (-not $groups[$key]) { $groups[$key] = @{ Name=$f.Name; Hash=$h; Size=$f.Length; Date=$f.LastWriteTime; Paths=@() } }
  $groups[$key].Paths += $f.FullName
}
Write-Output "`n=== INSTALLERS (deduped by SHA256) ==="
$groups.GetEnumerator() | Where-Object { $_.Value.Name -like 'NeuralShell Setup*' } |
  ForEach-Object { $v=$_.Value; [PSCustomObject]@{ Name=$v.Name; SizeMB=[math]::Round($v.Size/1MB,1); Date=$v.Date; Hash16=$v.Hash.Substring(0,16); PathCount=$v.Paths.Count; AfterMay2=($v.Date -gt $cutoff); SamplePath=$v.Paths[0] } } |
  Sort-Object SizeMB -Descending | Format-Table -AutoSize

Write-Output "`n=== APP.ASAR (deduped by SHA256) ==="
$groups.GetEnumerator() | Where-Object { $_.Value.Name -eq 'app.asar' } |
  ForEach-Object { $v=$_.Value; [PSCustomObject]@{ SizeMB=[math]::Round($v.Size/1MB,1); Date=$v.Date; Hash16=$v.Hash.Substring(0,16); PathCount=$v.Paths.Count; AfterMay2=($v.Date -gt $cutoff); SamplePath=$v.Paths[0] } } |
  Sort-Object Date -Descending | Format-Table -AutoSize

# Scan all js in release/final and May2 asar extract dirs for markers
$uiMarkers = @('AdaptiveLayoutEngine','PrimaryWorkspaceRegion','MultiWorkspace','LayoutControlBar','useAdaptiveLayoutChrome')
$scanDirs = @(
  'C:\Users\KickA\Projects\Active\NeuralShell\release\final',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\asar-full-release-232\dist-renderer',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\unpacked-release-232',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\silent-install-232-20260517',
  "$env:APPDATA\neuralshell-v5"
)
foreach ($dir in $scanDirs) {
  if (-not (Test-Path $dir)) { Write-Output "SKIP (missing): $dir"; continue }
  Write-Output "`n=== SCAN: $dir ==="
  $jsFiles = Get-ChildItem $dir -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.js','.css','.html' -and $_.Length -lt 5MB -and $_.Length -gt 0 }
  $markerHits = @{}
  foreach ($m in $uiMarkers) { $markerHits[$m] = @() }
  foreach ($f in $jsFiles) {
    try {
      $c = [IO.File]::ReadAllText($f.FullName)
      foreach ($m in $uiMarkers) {
        if ($c.Contains($m)) { $markerHits[$m] += $f.Name }
      }
    } catch {}
  }
  foreach ($m in $uiMarkers) {
    $files = $markerHits[$m] | Select-Object -Unique
    if ($files.Count -gt 0) { Write-Output "  $m -> $($files -join ', ')" }
    else { Write-Output "  $m -> (none)" }
  }
  # index bundles
  $indexes = Get-ChildItem $dir -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^index-[A-Za-z0-9_-]+\.(js|css)$' }
  if ($indexes) {
    Write-Output "  index bundles:"
    $indexes | Sort-Object LastWriteTime -Descending | Select-Object -First 10 | ForEach-Object { Write-Output "    $($_.Name) $($_.Length) $($_.LastWriteTime) $($_.DirectoryName)" }
  }
}

# List NeuralShell sibling folders and worktrees with dist-renderer
$dirs = @()
Get-ChildItem 'C:\Users\KickA\Projects\Active','C:\Users\KickA\Documents\GitHub' -Directory -Force -ErrorAction SilentlyContinue |
  Where-Object { $_.Name -match 'NeuralShell|neuralshell' } | ForEach-Object {
    $gitRoot = $null
    try { $gitRoot = git -C $_.FullName rev-parse --show-toplevel 2>$null } catch {}
    $hasDist = Test-Path (Join-Path $_.FullName 'dist-renderer')
    $hasRelease = Test-Path (Join-Path $_.FullName 'release\final')
    $hasValidation = Test-Path (Join-Path $_.FullName 'validation-artifacts')
    $indexFiles = @()
    if ($hasDist) {
      $indexFiles = Get-ChildItem (Join-Path $_.FullName 'dist-renderer') -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^index-.*\.js$' } | Select-Object -ExpandProperty Name
    }
    [PSCustomObject]@{
      Name=$_.Name; Path=$_.FullName; GitRoot=$gitRoot
      HasDistRenderer=$hasDist; HasReleaseFinal=$hasRelease; HasValidation=$hasValidation
      IndexBundles=($indexFiles -join ', ')
      LastWrite=$_.LastWriteTime
    }
  }
$dirs | Sort-Object LastWrite -Descending | Format-Table -AutoSize | Out-String -Width 500

# Extract index bundle from May 2 660MB asar using npx @electron/asar if available, or list
$asar660 = @(
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\unpacked-release-232\resources\app.asar',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\silent-install-232-20260517\resources\app.asar'
)
foreach ($a in $asar660) {
  if (Test-Path $a) {
    $i = Get-Item $a
    Write-Output "ASAR: $a"
    Write-Output "  Size=$($i.Length) Date=$($i.LastWriteTime) Hash=$((Get-FileHash $a -Algorithm SHA256).Hash.Substring(0,16))"
  }
}
# List unpacked-release-232 structure
$unpacked = 'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\unpacked-release-232'
if (Test-Path $unpacked) {
  Write-Output "`nUnpacked structure (top 3 levels):"
  Get-ChildItem $unpacked -Recurse -Depth 3 -Force -ErrorAction SilentlyContinue | Select-Object -First 40 FullName, Length, LastWriteTime | Format-Table -AutoSize
}
# release/final contents
$rf = 'C:\Users\KickA\Projects\Active\NeuralShell\release\final'
if (Test-Path $rf) {
  Write-Output "`nrelease/final tree:"
  Get-ChildItem $rf -Recurse -File -Force -ErrorAction SilentlyContinue | Select-Object Name, Length, LastWriteTime, DirectoryName | Sort-Object LastWriteTime -Descending | Format-Table -AutoSize
}

# Scan NeuralShell_clean_push and worktrees for markers in dist + source
$uiMarkers = @('AdaptiveLayoutEngine','PrimaryWorkspaceRegion','MultiWorkspace','LayoutControlBar','useAdaptiveLayoutChrome')
$targets = @(
  'C:\Users\KickA\Projects\Active\NeuralShell_clean_push',
  'C:\Users\KickA\Projects\Active\NeuralShell-wt-ui-regression\60abd6c',
  'C:\Users\KickA\Projects\Active\NeuralShell-wt-ui-regression\ea56e79',
  'C:\Users\KickA\Documents\GitHub\NeuralShell-Proof-Final-Clean'
)
foreach ($t in $targets) {
  if (-not (Test-Path $t)) { continue }
  Write-Output "`n=== $t ==="
  Write-Output "Git: $(git -C $t log -1 --format='%h %ci %s' 2>$null)"
  # source markers
  $srcHits = @()
  Get-ChildItem $t -Recurse -File -Force -ErrorAction SilentlyContinue |
    Where-Object { $_.Extension -in '.tsx','.ts','.jsx','.js' -and $_.FullName -match '\\src\\' -and $_.Length -lt 500000 } |
    ForEach-Object {
      try {
        $c = [IO.File]::ReadAllText($_.FullName)
        $hits = $uiMarkers | Where-Object { $c.Contains($_) }
        if ($hits) { $srcHits += "$($_.Name):$($hits -join '+')" }
      } catch {}
    }
  if ($srcHits) { Write-Output "  Source hits: $($srcHits | Select-Object -First 15 | Join-String -Separator '; ')" }
  else { Write-Output "  Source hits: none" }
  # dist index
  Get-ChildItem $t -Recurse -File -Force -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -match '^index-[A-Za-z0-9_-]+\.js$' -and $_.FullName -match 'dist-renderer' } |
    ForEach-Object {
      $c = [IO.File]::ReadAllText($_.FullName)
      $hits = $uiMarkers | Where-Object { $c.Contains($_) }
      Write-Output "  Bundle $($_.Name) ($($_.Length)b $($_.LastWriteTime)): markers=$($hits -join ',')"
    }
}

# Full marker scan across ALL js in asar-full-release-232 dist-renderer (chunked build)
$dir = 'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\asar-full-release-232\dist-renderer'
$uiMarkers = @('AdaptiveLayoutEngine','PrimaryWorkspaceRegion','MultiWorkspace','LayoutControlBar','useAdaptiveLayoutChrome')
$results = @()
Get-ChildItem $dir -Recurse -File -Filter '*.js' -Force | ForEach-Object {
  $c = [IO.File]::ReadAllText($_.FullName)
  $hits = $uiMarkers | Where-Object { $c.Contains($_) }
  if ($hits) {
    $results += [PSCustomObject]@{ File=$_.Name; Hits=$hits -join ','; Size=$_.Length; Path=$_.FullName }
  }
}
Write-Output "JS files with markers in asar-full-release-232/dist-renderer: $($results.Count)"
$results | Format-Table -AutoSize

# Count total js chunks
$allJs = Get-ChildItem $dir -Recurse -File -Filter '*.js' -Force
Write-Output "Total JS chunks: $($allJs.Count)"
Write-Output "index-CDfqmjqJ hash: $((Get-FileHash (Join-Path $dir 'js\index-CDfqmjqJ.js') -Algorithm SHA256).Hash.Substring(0,16))"

# List ui-recovery artifact folders with dates
$base = 'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery'
Get-ChildItem $base -Directory -Force | ForEach-Object {
  $indexes = Get-ChildItem $_.FullName -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^index-[A-Za-z0-9_-]+\.js$' -and $_.Length -gt 100000 }
  $installers = Get-ChildItem $_.FullName -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'NeuralShell Setup*.exe' }
  $asars = Get-ChildItem $_.FullName -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'app.asar' -and $_.Length -gt 1MB }
  [PSCustomObject]@{
    Folder=$_.Name
  LastWrite=$_.LastWriteTime
    IndexBundles=($indexes | ForEach-Object { "$($_.Name)($([math]::Round($_.Length/1KB))KB)" } | Select-Object -Unique) -join ', '
    Installers=($installers | ForEach-Object { "$($_.Name) $([math]::Round($_.Length/1MB))MB" } | Select-Object -Unique) -join '; '
    AsarMB=($asars | ForEach-Object { [math]::Round($_.Length/1MB) } | Select-Object -Unique) -join ', '
  }
} | Sort-Object LastWrite -Descending | Format-Table -AutoSize | Out-String -Width 500

# Verify layout chunks exist in asar-full-release-232 extract
$dir = 'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\asar-full-release-232\dist-renderer\js'
$patterns = @('AdaptiveLayout','PrimaryWorkspace','MultiWorkspace','LayoutControl','index-CDfqmjqJ')
foreach ($p in $patterns) {
  $matches = Get-ChildItem $dir -Filter "*$p*" -ErrorAction SilentlyContinue
  if ($matches) { Write-Output "$p -> $($matches.Name -join ', ')" } else { Write-Output "$p -> NOT FOUND" }
}
# Compare May2 asar hash vs release/final installer
$installer232 = 'C:\Users\KickA\Projects\Active\NeuralShell\release\final\bin\NeuralShell Setup 2.1.32.exe'
$installerCopy = 'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\installer-release-final-232-20260517-005800\NeuralShell Setup 2.1.32.exe'
foreach ($f in @($installer232, $installerCopy)) {
  if (Test-Path $f) {
    $i = Get-Item $f
    Write-Output "Installer: $f"
    Write-Output "  Size=$($i.Length) Date=$($i.LastWriteTime) Hash=$((Get-FileHash $f -Algorithm SHA256).Hash)"
  }
}

# Broad search: any file after May 2 containing PrimaryWorkspaceRegion or AdaptiveLayoutEngine-ThhiRTCa pattern
$cutoff = Get-Date '2026-05-02'
$patterns = @('PrimaryWorkspaceRegion','LayoutControlBar','useAdaptiveLayoutChrome','AdaptiveLayoutEngine-ThhiRTCa')
$searchRoots = @('C:\Users\KickA\Projects','C:\Users\KickA\Documents\GitHub')
$hits = @()
foreach ($root in $searchRoots) {
  Get-ChildItem $root -Recurse -File -Force -ErrorAction SilentlyContinue |
    Where-Object {
      $_.LastWriteTime -gt $cutoff -and $_.Length -lt 2MB -and $_.Length -gt 0 -and
      $_.FullName -match 'NeuralShell|neuralshell' -and
      $_.Extension -in '.js','.jsx','.ts','.tsx','.html'
    } | ForEach-Object {
      try {
        $c = [IO.File]::ReadAllText($_.FullName)
        $found = $patterns | Where-Object { $c.Contains($_) }
        if ($found) {
          $hits += [PSCustomObject]@{ File=$_.Name; Date=$_.LastWriteTime; Patterns=$found -join ','; Path=$_.FullName }
        }
      } catch {}
    }
}
