const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../..');
const outDir = path.join(__dirname, 'phase-1f-c3c-send-path-proof');
const mode = process.argv[2] || 'legacy';
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), `neuralshell-1fc3c-${mode}-`));
    const recoveryLogs = [];
    const consoleAll = [];
    const pageErrors = [];
    let app = null;

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: { ...process.env, NEURAL_USER_DATA_DIR: userDataDir, NEURAL_IGNORE_INTEGRITY: '1' },
        });
        const page = await app.firstWindow({ timeout: 180000 });
        page.on('console', (msg) => {
            const line = `[${msg.type()}] ${msg.text()}`;
            consoleAll.push(line);
            if (msg.text().includes('[recovery-send]')) recoveryLogs.push(line);
        });
        page.on('pageerror', (err) => pageErrors.push(String(err && err.message ? err.message : err)));

        await page.setViewportSize({ width: 1680, height: 980 });
        await page.waitForLoadState('domcontentloaded');
        await page.evaluate(() => {
            globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        });
        await page.reload();
        await page.waitForLoadState('domcontentloaded');
        await page.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 45000 });

        for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
            const btn = page.getByTestId(testId);
            if (await btn.count()) {
                await btn.first().click().catch(() => {});
                await page.waitForTimeout(250);
            }
        }

        await page.getByTestId('workspace-panel').waitFor({ state: 'visible', timeout: 30000 });
        await page.getByTestId('chat-input').first().waitFor({ state: 'visible', timeout: 15000 });

        const shotBefore = path.join(outDir, `${mode}-before-help-${stamp}.png`);
        await page.screenshot({ path: shotBefore });

        const chatInput = page.getByTestId('chat-input').first();
        await chatInput.fill('/help');
        const t0 = Date.now();
        await chatInput.press('Enter');
        await page.waitForTimeout(100);
        const logsAt100ms = recoveryLogs.length;
        await page.waitForTimeout(500);
        const logsAt600ms = recoveryLogs.length;

        const shotAfter = path.join(outDir, `${mode}-after-help-${stamp}.png`);
        await page.screenshot({ path: shotAfter });

        let paneAssistant = '';
        let globalKernel = '';
        try {
            paneAssistant = await page.locator('[data-testid="chat-message"]').last().textContent({ timeout: 3000 }) || '';
        } catch {
            paneAssistant = await page.locator('text=/NodeChain|Operator Guide|NeuralShell Operator/i').first().textContent({ timeout: 2000 }).catch(() => '') || '';
        }

        await page.getByTestId('settings-open-btn').click({ timeout: 5000 }).catch(() => {});
        await page.waitForTimeout(500);
        const settingsOpen = await page.getByTestId('settings-drawer').isVisible().catch(() => false);
        const shotSettings = path.join(outDir, `${mode}-settings-${stamp}.png`);
        await page.screenshot({ path: shotSettings });
        if (settingsOpen) {
            await page.getByTestId('settings-close-btn').click({ timeout: 5000 }).catch(() => {});
            await page.waitForTimeout(200);
        }

        await chatInput.click().catch(() => {});
        await page.keyboard.press('Control+K');
        await page.waitForTimeout(500);
        const paletteOpen = await page.getByTestId('command-palette').isVisible().catch(() => false);
        const shotPaletteK = path.join(outDir, `${mode}-palette-ctrlk-${stamp}.png`);
        await page.screenshot({ path: shotPaletteK });
        await page.keyboard.press('Escape');
        await page.waitForTimeout(200);

        await page.getByTestId('command-palette-btn').click({ timeout: 5000 }).catch(() => {});
        await page.waitForTimeout(500);
        const paletteExecOpen = await page.getByTestId('command-palette').isVisible().catch(() => false);
        const shotPaletteExec = path.join(outDir, `${mode}-palette-exec-${stamp}.png`);
        await page.screenshot({ path: shotPaletteExec });
        await page.keyboard.press('Escape');

        const logFile = path.join(outDir, `${mode}-console-${stamp}.log`);
        fs.writeFileSync(logFile, [...recoveryLogs, '', '--- all console ---', ...consoleAll].join('\n'));

        const report = {
            mode,
            capturedAt: new Date().toISOString(),
            shotBefore,
            shotAfter,
            shotSettings,
            shotPaletteK,
            shotPaletteExec,
            logFile,
            recoveryLogCount: recoveryLogs.length,
            recoveryLogsAt100ms: logsAt100ms,
            recoveryLogsAt600ms: logsAt600ms,
            paneAssistantSnippet: String(paneAssistant).slice(0, 200),
            hasOperatorGuide: String(paneAssistant).includes('NeuralShell Operator Guide') || String(paneAssistant).includes('Operator Guide'),
            hasNodeChainVault: String(paneAssistant).includes('NodeChain prompted a vault save'),
            settingsDrawer: settingsOpen,
            paletteCtrlK: paletteOpen,
            paletteExecBtn: paletteExecOpen,
            pageErrors,
            recoveryLogs,
        };
        fs.writeFileSync(path.join(outDir, `${mode}-report-${stamp}.json`), JSON.stringify(report, null, 2));
        console.log(JSON.stringify(report, null, 2));
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

main().catch((e) => { console.error(e); process.exit(1); });

