const root = path.join(__dirname, '../..');

async function main() {
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-collab-b-'));
    const consoleErrors = [];
    const pageErrors = [];
    let app = null;

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: { ...process.env, NEURAL_USER_DATA_DIR: userDataDir, NEURAL_IGNORE_INTEGRITY: '1' },
        });
        const page = await app.firstWindow({ timeout: 180000 });
        page.on('console', (msg) => {
            if (msg.type() === 'error') consoleErrors.push(msg.text());
        });
        page.on('pageerror', (err) => pageErrors.push(String(err && err.message ? err.message : err)));

        await page.setViewportSize({ width: 1680, height: 980 });
        await page.waitForLoadState('domcontentloaded');
        await page.evaluate(() => {
            globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
