async function waitForCollabConnected(page, label, timeoutMs = 60000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
        const probe = await readCollabProbe(page);
        const serverUp = probe.status && probe.status.running && !probe.status.error;
        const pillOn = probe.pillText && !/collab off/i.test(probe.pillText);
        if (serverUp && pillOn) {
            return probe;
        }
        await page.waitForTimeout(500);
    }
    const last = await readCollabProbe(page);
    throw new Error(`Collab did not connect on ${label} within ${timeoutMs}ms; last=${JSON.stringify(last)}`);
}

