async function measureWidths(page) {
    return page.evaluate(() => {
        const panel = document.querySelector('[data-testid="workspace-panel"]');
        const deck = document.querySelector('[data-testid="capabilities-matrix"]');
        const hero = Array.from(document.querySelectorAll('h2')).find((h) => h.textContent.includes('Operator Hero Console'));
        const panelRect = panel ? panel.getBoundingClientRect() : null;
        const deckRect = deck ? deck.getBoundingClientRect() : null;
        const heroBlock = hero ? hero.closest('.max-w-6xl, .max-w-3xl, [class*="max-w"]') || hero.parentElement : null;
        const heroRect = heroBlock ? heroBlock.getBoundingClientRect() : null;
        return {
            workspacePanelWidth: panelRect ? Math.round(panelRect.width) : 0,
            capabilitiesMatrixWidth: deckRect ? Math.round(deckRect.width) : 0,
            heroBlockWidth: heroRect ? Math.round(heroRect.width) : 0,
        };
    });
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-1g-layout-width-'));
    const pageErrors = [];
    const consoleErrors = [];
    let app;

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: {
                ...process.env,
                NEURAL_USER_DATA_DIR: userDataDir,
                NEURAL_IGNORE_INTEGRITY: '1',
                NEURAL_COLLAB_TEST_CSP: '1',
            },
        });
        const page = await app.firstWindow({ timeout: 180000 });
        page.on('pageerror', (e) => pageErrors.push(String(e)));
        page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });

        await page.setViewportSize({ width: 1440, height: 900 });
        await page.evaluate(() => localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1'));
        await page.reload({ waitUntil: 'domcontentloaded' });
        await page.getByTestId('top-status-bar').waitFor({ timeout: 60000 });
        await dismissOverlays(page);
        await page.getByTestId('workspace-panel').waitFor({ timeout: 30000 });

        const widthsBefore = await measureWidths(page);
        const shots = { initial: await shot(page, '01-initial-empty-state') };

        await sendChat(page, '/help');
        await page.waitForTimeout(2000);
        const helpText = await page.getByTestId('workspace-panel').innerText();
        const helpOk = helpText.includes('NeuralShell Operator Guide');
        shots.afterHelp = await shot(page, '02-after-help');

        await sendChat(page, 'test 1g layout width send');
        await page.waitForTimeout(2500);
        const freeformText = await page.getByTestId('workspace-panel').innerText();
        const freeformOk = freeformText.toLowerCase().includes('test 1g layout width send');
        shots.afterFreeform = await shot(page, '03-after-freeform');

        const report = {
            capturedAt: new Date().toISOString(),
            slice: '1G-LAYOUT-WIDTH',
            viewport: { width: 1440, height: 900 },
            widthsBefore,
            helpOk,
            freeformOk,
            pageErrors,
            consoleErrors,
            shots,
            checks: {
                clock: await page.getByTestId('clock-calendar-btn').isVisible().catch(() => false),
                layoutBar: await page.getByTestId('layout-control-bar').isVisible().catch(() => false),
                hero: await page.getByText('Operator Hero Console').first().isVisible().catch(() => false),
                controlDeck: await page.getByText('Control Deck').first().isVisible().catch(() => false),
                chatInput: await page.getByTestId('chat-input').first().isVisible().catch(() => false),
            },
        };
        fs.writeFileSync(path.join(outDir, `layout-width-report-${stamp}.json`), JSON.stringify(report, null, 2));
        console.log(JSON.stringify(report, null, 2));
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

main().catch((e) => { console.error(e); process.exit(1); });

