const fs = require('fs');
const os = require('os');
const path = require('path');
const { execSync } = require('child_process');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../..');
const outDir = path.join(__dirname, 'phase-final-hardened-package-proof');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const installDir = process.env.NS_INSTALLED_DIR || path.join(process.env.LOCALAPPDATA || '', 'Programs', 'NeuralShell');
const exePath = path.join(installDir, 'NeuralShell.exe');

function sha256(filePath) {
    try {
        const out = execSync(`certutil -hashfile "${filePath}" SHA256`, { encoding: 'utf8' });
        const line = out.split(/\r?\n/).find((l) => /^[0-9a-fA-F]{64}$/.test(l.trim()));
        return line ? line.trim().toUpperCase() : null;
    } catch {
        return null;
    }
}

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) await btn.first().click().catch(() => {});
    }
    await page.evaluate(() => {
        localStorage.setItem('neuralshell_first_boot_completed_v1', '1');
        localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
    });
}

async function shot(page, name) {
    const p = path.join(outDir, `${name}-${stamp}.png`);
    await page.screenshot({ path: p, fullPage: false });
    return p;
}

async function sendChatViaInput(page, text) {
    const chatInput = page.getByTestId('chat-input').first();
    await chatInput.click({ timeout: 10000 });
    await chatInput.fill(text);
    await chatInput.press('Enter');
}

function isBenignConsoleError(text) {
    const t = String(text || '');
    return t.includes('ERR_BLOCKED_BY_CLIENT') || t.includes('Content Security Policy') || t.includes('Refused to connect');
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-final-hardened-proof-'));
    const pageErrors = [];
    const consoleErrors = [];
    const consoleBenign = [];
    let app;

    let registryVersion = null;
    try {
        const out = execSync('reg query HKCU\\Software\\NeuralShell /v Version', { encoding: 'utf8' });
        const m = out.match(/Version\s+REG_SZ\s+(\S+)/i);
        registryVersion = m ? m[1] : null;
    } catch {
        registryVersion = null;
    }

    try {
        app = await electron.launch({
            executablePath: exePath,
            args: ['.'],
            cwd: installDir,
            timeout: 120000,
            env: {
                ...process.env,
                NEURAL_USER_DATA_DIR: userDataDir,
                NEURAL_IGNORE_INTEGRITY: '1',
                NEURAL_COLLAB_TEST_CSP: '1',
            },
        });
        const page = await app.firstWindow({ timeout: 180000 });
        page.on('pageerror', (e) => pageErrors.push(String(e)));
        page.on('console', (msg) => {
            if (msg.type() !== 'error') return;
            const text = msg.text();
            if (isBenignConsoleError(text)) consoleBenign.push(text);
            else consoleErrors.push(text);
        });

