        await page.reload({ waitUntil: 'domcontentloaded' });
        await page.getByTestId('top-status-bar').waitFor({ timeout: 90000 });
        await dismissOverlays(page);
        await page.getByTestId('workspace-panel').waitFor({ timeout: 30000 });

        const versionObserved = await page.evaluate(() => document.body.innerText.slice(0, 800));
        const shots = { initial: await shot(page, '01-initial-recovered-shell') };

        const checks = {
            versionInChrome: /v?2\.1\.33/i.test(versionObserved),
            clock: await page.getByTestId('clock-calendar-btn').isVisible().catch(() => false),
            layoutBar: await page.getByTestId('layout-control-bar').isVisible().catch(() => false),
            hero: await page.getByText('Operator Hero Console').first().isVisible().catch(() => false),
            controlDeck: await page.getByText('Control Deck').first().isVisible().catch(() => false),
            workbenchRail: await page.getByTestId('workbench-rail').isVisible().catch(() => false),
