const PROVIDER_ROLES = new Set(['system', 'user', 'assistant']);

const INTERNAL_ROLE_ALIASES = {
    kernel: 'assistant',
    operator: 'assistant',
};

/**
 * Map internal UI chat rows to provider-safe llm:chat / streamChat payloads.
 * Does not mutate the source log; kernel rows remain in UI state.
 */
export function toProviderMessages(log) {
    if (!Array.isArray(log)) return [];

    return log
        .filter((entry) => entry && typeof entry === 'object')
        .map((entry) => {
            const rawRole = String(entry.role || '').trim().toLowerCase();
            const mapped = INTERNAL_ROLE_ALIASES[rawRole] || rawRole;
            const content = typeof entry.content === 'string'
                ? entry.content
                : String(entry.content ?? '');
            return { role: mapped, content };
        })
        .filter((entry) => PROVIDER_ROLES.has(entry.role) && entry.content.trim().length > 0);
}

const assert = require('node:assert/strict');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { validateMessages } = require('../src/core/ipcValidators');

async function loadHelper() {
    const mod = await import(pathToFileURL(path.join(__dirname, '../src/renderer/src/lib/toProviderMessages.js')).href);
    return mod.toProviderMessages;
}

async function run() {
    const toProviderMessages = await loadHelper();

    const normalized = toProviderMessages([
        { role: 'kernel', content: '### NeuralShell Operator Guide' },
        { role: 'operator', content: 'operator note' },
        { role: 'user', content: 'hello' },
        { role: 'assistant', content: 'prior reply' },
        { role: 'kernel', content: '   ' },
        { role: 'narrator', content: 'drop me' },
    ]);

    assert.deepEqual(normalized, [
        { role: 'assistant', content: '### NeuralShell Operator Guide' },
        { role: 'assistant', content: 'operator note' },
        { role: 'user', content: 'hello' },
        { role: 'assistant', content: 'prior reply' },
    ]);

    assert.doesNotThrow(() => validateMessages(normalized));

    const withUser = toProviderMessages([
        { role: 'kernel', content: 'guide text' },
        { role: 'user', content: 'follow-up question' },
    ]);
    assert.doesNotThrow(() => validateMessages(withUser));
    assert.equal(withUser[withUser.length - 1].role, 'user');

    console.log('PASS toProviderMessages');
}

run().catch((err) => {
    console.error(err);
    process.exit(1);
});

