const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../../..');
const outDir = __dirname;
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const exePath = process.env.NS_EXE_PATH || path.join(root, 'dist', 'win-unpacked', 'NeuralShell.exe');
const useDist = fs.existsSync(exePath);

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) await btn.first().click().catch(() => {});
    }
    await page.evaluate(() => {
        localStorage.setItem('neuralshell_first_boot_completed_v1', '1');
        localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
    });
}

async function sendChat(page, text) {
    const chatInput = page.getByTestId('chat-input').first();
    await chatInput.click({ timeout: 10000 });
    await chatInput.fill(text);
    await chatInput.press('Enter');
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-kernel-role-hotfix-'));
    const env = {
        ...process.env,
        NEURAL_USER_DATA_DIR: userDataDir,
        NEURAL_IGNORE_INTEGRITY: '1',
        NEURAL_COLLAB_TEST_CSP: '1',
    };
    const launchOpts = useDist
        ? { executablePath: exePath, args: ['.'], cwd: path.dirname(exePath), timeout: 120000, env }
        : { args: [root], cwd: root, timeout: 120000, env };

    let app;
    const pageErrors = [];
    const consoleErrors = [];

    try {
        app = await electron.launch(launchOpts);
        const page = await app.firstWindow({ timeout: 180000 });
        page.on('pageerror', (e) => pageErrors.push(String(e)));
        page.on('console', (msg) => {
            if (msg.type() === 'error') consoleErrors.push(msg.text());
        });

        await page.setViewportSize({ width: 1200, height: 900 });
        await dismissOverlays(page);
        await page.reload({ waitUntil: 'domcontentloaded' });
        await page.getByTestId('top-status-bar').waitFor({ timeout: 90000 });
        await dismissOverlays(page);
        await page.getByTestId('workspace-panel').waitFor({ timeout: 30000 });

        await sendChat(page, '/help');
        await page.waitForTimeout(2500);
        const helpText = await page.getByTestId('workspace-panel').innerText();
        const helpOk = helpText.includes('Operator Guide');
        const shotHelp = path.join(outDir, `01-after-help-${stamp}.png`);
        await page.screenshot({ path: shotHelp, fullPage: false });

        await sendChat(page, 'kernel role hotfix smoke follow-up');
        await page.waitForTimeout(5000);
        const afterText = await page.getByTestId('workspace-panel').innerText();
        const kernelRoleError = /invalid message role:\s*kernel/i.test(afterText)
            || consoleErrors.some((t) => /invalid message role:\s*kernel/i.test(t))
            || pageErrors.some((t) => /invalid message role:\s*kernel/i.test(t));
        const hasKernelErrorUi = afterText.includes('Kernel Error:') && afterText.includes('invalid message role');
        const freeformOk = !kernelRoleError && !hasKernelErrorUi;
        const shotFreeform = path.join(outDir, `02-after-freeform-${stamp}.png`);
        await page.screenshot({ path: shotFreeform, fullPage: false });

        const report = {
            capturedAt: new Date().toISOString(),
            launchMode: useDist ? 'dist-win-unpacked' : 'electron-dev',
            exePath: useDist ? exePath : root,
            helpOk,
            freeformOk,
            kernelRoleError,
            hasKernelErrorUi,
            helpSnippet: helpText.slice(0, 300),
            afterSnippet: afterText.slice(0, 400),
            pageErrors,
            consoleErrors: consoleErrors.filter((t) => !t.includes('ERR_BLOCKED_BY_CLIENT')),
            shots: { afterHelp: shotHelp, afterFreeform: shotFreeform },
            pass: helpOk && freeformOk,
        };
        const reportPath = path.join(outDir, `kernel-role-hotfix-smoke-${stamp}.json`);
        fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
        console.log(JSON.stringify({ ...report, reportPath }, null, 2));
        if (!report.pass) process.exit(1);
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

main().catch((e) => { console.error(e); process.exit(1); });

