/**
 * Extended smoke: kernel-role isolation (freeform before/after /help).
 * Fresh userData via NEURAL_USER_DATA_DIR; electron-dev from repo root.
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../../..');
const outDir = __dirname;
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) await btn.first().click().catch(() => {});
    }
    await page.evaluate(() => {
        localStorage.setItem('neuralshell_first_boot_completed_v1', '1');
        localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
    });
}

async function sendChat(page, text) {
    const chatInput = page.getByTestId('chat-input').first();
    await chatInput.click({ timeout: 10000 });
    await chatInput.fill(text);
    await chatInput.press('Enter');
}

function chatHasKernelRoleError(text) {
    return /invalid message role:\s*kernel/i.test(text);
}

async function waitForKernelReply(page, timeoutMs = 45000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
        const logText = await page.getByTestId('workspace-panel').innerText().catch(() => '');
        if (/Kernel Error:/i.test(logText) || /System: Empty response/i.test(logText)) {
            const lastKernel = (logText.match(/Kernel Error:[^\n]+/gi) || []).pop() || '';
            return { done: true, error: lastKernel, logSnippet: logText.slice(-400) };
        }
        if (logText.includes('say ok') && !/is thinking/i.test(logText)) {
            const idx = logText.lastIndexOf('say ok');
            const after = logText.slice(idx, idx + 200);
            if (after.length > 20 && !after.includes('...')) {
                return { done: true, error: '', logSnippet: logText.slice(-400) };
            }
        }
        await page.waitForTimeout(800);
    }
    return { done: false, error: 'timeout', logSnippet: '' };
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-kernel-seq-'));
    const env = {
        ...process.env,
        NEURAL_USER_DATA_DIR: userDataDir,
        NEURAL_IGNORE_INTEGRITY: '1',
        NEURAL_COLLAB_TEST_CSP: '1',
    };

    const report = {
        capturedAt: new Date().toISOString(),
        launchMode: 'electron-dev',
        repoRoot: root,
        userDataDir,
        runtimeContext: {},
        sequence: {},
        pass: false,
    };

    let app;
    try {
        app = await electron.launch({ args: [root], cwd: root, timeout: 120000, env });
        const page = await app.firstWindow({ timeout: 180000 });
        await page.setViewportSize({ width: 1200, height: 900 });
        await dismissOverlays(page);
        await page.reload({ waitUntil: 'domcontentloaded' });
        await page.getByTestId('top-status-bar').waitFor({ timeout: 90000 });
        await dismissOverlays(page);
        await page.waitForTimeout(2500);

        report.runtimeContext = await page.evaluate(() => {
            const keys = [
                'neuralshell_appliance_mode_v1',
                'neuralshell_airgap_mode_v1',
                'neuralshell_first_boot_completed_v1',
                'neuralshell_onboarding_dismissed_v1',
            ];
            const ls = {};
            keys.forEach((k) => { ls[k] = localStorage.getItem(k); });
            return {
                localStorage: ls,
                topBar: document.querySelector('[data-testid="top-status-bar"]')?.innerText?.slice(0, 300) || '',
                applianceOffVisible: /APPLIANCE OFF/i.test(document.body.innerText),
                auditOnlyVisible: /AUDIT-ONLY/i.test(document.body.innerText),
            };
        });

        await page.screenshot({ path: path.join(outDir, `seq-01-before-${stamp}.png`) });

        await sendChat(page, 'say ok direct before help');
        const beforeHelp = await waitForKernelReply(page);
        report.sequence.directFreeformBeforeHelp = {
            ok: beforeHelp.done && !chatHasKernelRoleError(beforeHelp.error),
            kernelRoleError: chatHasKernelRoleError(beforeHelp.error),
            error: beforeHelp.error,
        };
        await page.screenshot({ path: path.join(outDir, `seq-02-after-direct-${stamp}.png`) });

        await sendChat(page, '/help');
        await page.waitForTimeout(2500);
        const helpText = await page.getByTestId('workspace-panel').innerText().catch(() => '');
        report.sequence.help = { ok: /Operator Guide/i.test(helpText) };

        await sendChat(page, 'say ok after help');
        const afterHelp = await waitForKernelReply(page);
        report.sequence.freeformAfterHelp = {
            ok: afterHelp.done && !chatHasKernelRoleError(afterHelp.error),
            kernelRoleError: chatHasKernelRoleError(afterHelp.error),
            error: afterHelp.error,
        };
        await page.screenshot({ path: path.join(outDir, `seq-03-after-help-freeform-${stamp}.png`) });

        report.sequence.kernelBugIsPrimaryChatBlocker =
            report.sequence.directFreeformBeforeHelp.ok
            && report.sequence.freeformAfterHelp.ok
            && !report.sequence.directFreeformBeforeHelp.kernelRoleError
            && !report.sequence.freeformAfterHelp.kernelRoleError;

        report.sequence.kernelBugOnlyAfterHelp =
            report.sequence.directFreeformBeforeHelp.ok
            && !report.sequence.freeformAfterHelp.ok
            && report.sequence.freeformAfterHelp.kernelRoleError;

        report.pass =
            report.sequence.help.ok
            && report.sequence.freeformAfterHelp.ok
            && !report.sequence.freeformAfterHelp.kernelRoleError;

        const outJson = path.join(outDir, `kernel-sequence-smoke-${stamp}.json`);
        fs.writeFileSync(outJson, JSON.stringify(report, null, 2));
        report.reportPath = outJson;
        console.log(JSON.stringify(report, null, 2));
    } finally {
        if (app) await app.close().catch(() => {});
    }
    process.exit(report.pass ? 0 : 1);
}

main().catch((err) => {
    console.error(err);
    process.exit(1);
});

