async function waitForChatOutcome(page, needle, timeoutMs = 50000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
        const logText = await page.getByTestId('workspace-panel').innerText().catch(() => '');
        const kernelErr = (logText.match(/Kernel Error:[^\n]+/gi) || []).pop() || '';
        if (kernelErr) {
            return {
                done: true,
                ok: false,
                kernelRoleError: chatHasKernelRoleError(kernelErr),
                error: kernelErr,
                logSnippet: logText.slice(-500),
            };
        }
        if (logText.includes(needle) && !/is thinking/i.test(logText)) {
            const idx = logText.lastIndexOf(needle);
            const tail = logText.slice(idx);
            if (tail.length > needle.length + 5) {
                return { done: true, ok: true, kernelRoleError: false, error: '', logSnippet: logText.slice(-500) };
            }
        }
        await page.waitForTimeout(700);
    }
    return { done: false, ok: false, kernelRoleError: false, error: 'timeout', logSnippet: '' };
}

function interpretSequence(seq) {
    const a = seq.stepA_directFreeform;
    const b = seq.stepB_afterHelp;
    if (a.ok && !b.ok && b.kernelRoleError) {
        return 'kernel_role_confirmed_A_ok_B_fails';
    }
    if (!a.ok && !b.ok) {
        return 'ollama_or_provider_setup_separate';
    }
    if (a.ok && b.ok) {
        return 'both_ok_normalization_or_no_kernel_poison';
    }
    if (a.ok && !b.ok && !b.kernelRoleError) {
        return 'A_ok_B_fails_non_kernel';
    }
    return 'inconclusive';
}

