/**
 * HOTFIX-2134 proof harness — strict assistant-response detection.
 * Usage: node _tmp-hotfix-proof.cjs <dev|installed>
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');
const { toProviderMessages } = require('../../../src/renderer/src/lib/toProviderMessages.js');

const root = path.join(__dirname, '../../..');
const mode = String(process.argv[2] || 'dev').toLowerCase();
const installedExe = path.join(process.env.LOCALAPPDATA || '', 'Programs', 'NeuralShell', 'NeuralShell.exe');
const outRoot = path.join(__dirname, mode === 'installed' ? 'installed-proof' : 'dev-proof');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

const PROMPT_A = 'say ok';
const PROMPT_B = 'say ok after help';
const WAIT_MS = 90000;

const NON_LLM_ASSISTANT = [
    /NodeChain prompted a vault save/i,
    /Audit-only mode accepts proof/i,
    /Audit-only mode blocked command/i,
    /^Unknown command:/i,
    /^Security Guard:/i,
    /^Node Status:/i,
];

const KERNEL_ROLE_RE = /invalid message role:\s*kernel/i;

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) await btn.first().click().catch(() => {});
    }
    await page.evaluate(() => {
        localStorage.setItem('neuralshell_first_boot_completed_v1', '1');
        localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        localStorage.setItem('neuralshell_appliance_mode_v1', '0');
        localStorage.setItem('neuralshell_airgap_mode_v1', '0');
    });
}

async function sendChat(page, text) {
    const chatInput = page.getByTestId('chat-input').first();
    await chatInput.click({ timeout: 15000 });
    await chatInput.fill(text);
    await chatInput.press('Enter');
}

async function readChatMessages(page) {
    return page.evaluate(() => {
        const nodes = Array.from(document.querySelectorAll('[data-testid="chat-message"]'));
        return nodes.map((el) => {
            const isUser = el.classList.contains('flex-row-reverse');
            const bubble = el.querySelector('.whitespace-pre-wrap');
            const text = bubble ? String(bubble.textContent || '').trim() : '';
            return { isUser, text };
        });
    });
}

function classifyAssistantText(text, { expectOperatorGuide = false } = {}) {
    const t = String(text || '').trim();
    if (!t) return { kind: 'empty', ok: false };
    if (KERNEL_ROLE_RE.test(t)) return { kind: 'kernel_role_error', ok: false, text: t.slice(0, 200) };
    if (/^Kernel Error:/i.test(t)) {
        const setup = /fetch failed|connection refused|ECONNREFUSED|404|model.*not found|offline|not detected/i.test(t);
        return { kind: setup ? 'provider_setup_error' : 'kernel_error', ok: false, text: t.slice(0, 240) };
    }
    if (expectOperatorGuide && /NeuralShell Operator Guide/i.test(t)) {
        return { kind: 'operator_guide', ok: true, text: 'Operator Guide present' };
    }
    if (NON_LLM_ASSISTANT.some((re) => re.test(t))) {
        return { kind: 'non_llm_assistant', ok: false, text: t.slice(0, 200) };
    }
    if (/^### NeuralShell Operator Guide/i.test(t)) {
        return { kind: 'operator_guide', ok: expectOperatorGuide, text: t.slice(0, 80) };
    }
    return { kind: 'llm_or_freeform_reply', ok: true, text: t.slice(0, 240) };
}

async function waitForAssistantAfterPrompt(page, userPrompt, opts = {}) {
    const baseline = await readChatMessages(page);
    const baselineAssistant = baseline.filter((m) => !m.isUser).length;
    const start = Date.now();
    let last = null;

    while (Date.now() - start < WAIT_MS) {
        const msgs = await readChatMessages(page);
        const assistants = msgs.filter((m) => !m.isUser);
        if (assistants.length > baselineAssistant) {
            const newAssistants = assistants.slice(baselineAssistant);
            const candidate = newAssistants[newAssistants.length - 1];
            const classified = classifyAssistantText(candidate.text, opts);
            last = { ...classified, assistantCount: assistants.length, waitedMs: Date.now() - start };
            if (classified.kind === 'kernel_role_error' || classified.kind === 'kernel_error' || classified.kind === 'provider_setup_error') {
                return last;
            }
            if (classified.kind === 'non_llm_assistant') {
                await page.waitForTimeout(500);
                continue;
            }
            if (opts.expectOperatorGuide && classified.kind === 'operator_guide') {
                return last;
            }
            if (!opts.expectOperatorGuide && classified.ok && classified.kind === 'llm_or_freeform_reply') {
                return last;
            }
        }
        await page.waitForTimeout(400);
    }
    return last || { kind: 'timeout', ok: false, text: '', waitedMs: WAIT_MS };
}

async function probeRuntime(page) {
    return page.evaluate(async () => {
        const health = window.api?.llm?.health ? await window.api.llm.health().catch((e) => ({ ok: false, reason: e.message })) : null;
        const settings = window.api?.settings?.get ? await window.api.settings.get().catch(() => ({})) : {};
        const state = window.api?.state?.get ? await window.api.state.get().catch(() => ({})) : {};
        const topBar = document.querySelector('[data-testid="top-status-bar"]')?.innerText?.slice(0, 400) || '';
        const deck = document.querySelector('[data-testid="capabilities-matrix"]')?.innerText?.slice(0, 200) || '';
        return {
            health: health ? { ok: health.ok, provider: health.provider, model: health.model, baseUrl: health.baseUrl, reason: health.reason || '' } : null,
            settings: {
                provider: settings?.provider,
                model: settings?.model,
                ollamaBaseUrl: settings?.ollamaBaseUrl,
                allowRemoteBridge: settings?.allowRemoteBridge,
                tier: settings?.tier,
            },
            stateModel: state?.model,
            topBarSnippet: topBar,
            deckSnippet: deck,
        };
    });
}

function assertProviderRoles(log) {
    const payload = toProviderMessages(log);
    const roles = payload.map((m) => m.role);
    const invalid = roles.filter((r) => !['system', 'user', 'assistant'].includes(r));
    return { roles, invalid, ok: invalid.length === 0 };
}

