        sequence: {},
        pass: false,
    };

    const launchOpts = useInstalled
        ? { executablePath: installedExe, args: ['.'], cwd: path.dirname(installedExe), timeout: 120000, env }
        : { args: [root], cwd: root, timeout: 120000, env };

    let app;
    try {
