            { role: 'user', content: PROMPT_B },
        ]);

        await page.screenshot({ path: path.join(outRoot, `proof-${stamp}-00-initial.png`) });

        // Step A
        await sendChat(page, PROMPT_A);
        report.sequence.stepA = {
            prompt: PROMPT_A,
