        };
        await page.screenshot({ path: path.join(outRoot, `proof-${stamp}-01-stepA.png`) });

        // /help
        await sendChat(page, '/help');
        report.sequence.help = {
            result: await waitForAssistantAfterPrompt(page, '/help', { expectOperatorGuide: true }),
        };
        await page.screenshot({ path: path.join(outRoot, `proof-${stamp}-02-help.png`) });

        // Step B
        await sendChat(page, PROMPT_B);
        report.sequence.stepB = {
            prompt: PROMPT_B,
            result: await waitForAssistantAfterPrompt(page, PROMPT_B),
        };
        await page.screenshot({ path: path.join(outRoot, `proof-${stamp}-03-stepB.png`) });

        report.runtimeAfter = await probeRuntime(page);

        const a = report.sequence.stepA.result;
        const h = report.sequence.help.result;
        const b = report.sequence.stepB.result;

        report.sequence.interpretation =
            a?.ok && !b?.ok && b?.kind === 'kernel_role_error'
                ? 'kernel_role_confirmed_A_ok_B_kernel_error'
                : !a?.ok && !b?.ok
                    ? 'both_fail_provider_or_setup'
                    : a?.ok && b?.ok
                        ? 'both_llm_replies_ok'
                        : a?.ok && !b?.ok
                            ? 'A_ok_B_fail_other'
                            : 'inconclusive';

        report.pass = Boolean(
            h?.ok
            && a?.ok
            && a?.kind === 'llm_or_freeform_reply'
            && b?.ok
            && b?.kind === 'llm_or_freeform_reply'
            && !KERNEL_ROLE_RE.test(b?.text || '')
            && report.payloadRolesSample?.ok
        );

        const outJson = path.join(outRoot, `hotfix-proof-${stamp}.json`);
        fs.writeFileSync(outJson, JSON.stringify(report, null, 2));
        report.reportPath = outJson;
        console.log(JSON.stringify(report, null, 2));
    } finally {
        if (app) await app.close().catch(() => {});
    }
    process.exit(report.pass ? 0 : 1);
}

main().catch((err) => {
    console.error(err);
    process.exit(1);
});

