/** Installed v2.1.33 IPC repro — kernel role rejection (no UI). */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const installedExe = path.join(process.env.LOCALAPPDATA || '', 'Programs', 'NeuralShell', 'NeuralShell.exe');
const outDir = path.join(__dirname, 'installed-proof');

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ns-installed-ipc-'));
    const env = {
        ...process.env,
        NEURAL_USER_DATA_DIR: userDataDir,
        NEURAL_IGNORE_INTEGRITY: '1',
        NEURAL_COLLAB_TEST_CSP: '1',
        LICENSE_MODE: 'preview',
    };
    const report = { executable: installedExe, pass: false };
    let app;
    try {
        app = await electron.launch({
            executablePath: installedExe,
            args: ['.'],
            cwd: path.dirname(installedExe),
            timeout: 120000,
            env,
        });
        const page = await app.firstWindow({ timeout: 120000 });
        page.setDefaultTimeout(120000);
        await page.waitForTimeout(10000);
        report.ipc = await page.evaluate(async () => {
            const bad = await window.api.llm.chat([
                { role: 'kernel', content: '### NeuralShell Operator Guide' },
                { role: 'user', content: 'say ok after help' },
            ]).then(() => ({ ok: true })).catch((e) => ({ ok: false, error: String(e.message || e) }));
            return { badPayload: bad };
        });
        report.pass = Boolean(report.ipc?.badPayload && !report.ipc.badPayload.ok
            && /invalid message role:\s*kernel/i.test(report.ipc.badPayload.error || ''));
        report.note = 'Installed build lacks toProviderMessages; kernel IPC rejection expected. Fixed proof: dev node-provider-proof + hotfix branch.';
    } finally {
        if (app) await app.close().catch(() => {});
    }
    const out = path.join(outDir, `installed-ipc-repro-${Date.now()}.json`);
    fs.writeFileSync(out, JSON.stringify(report, null, 2));
    console.log(JSON.stringify(report, null, 2));
    process.exit(report.pass ? 0 : 1);
}

main().catch((e) => { console.error(e); process.exit(1); });

