import React from 'react';

/**
 * Workflow / session picker surfaced from MultiWorkspace "Projects" (recovery P0).
 */
export default function ProjectsModePanel({
    sessions = [],
    workflowId,
    onSelectSession,
    onCreateSession,
}) {
    const rows = Array.isArray(sessions) ? sessions : [];
    const activeId = String(workflowId || '');

    return (
        <section data-testid="projects-mode-panel" className="space-y-4">
            <p className="text-[11px] font-mono text-slate-400 leading-relaxed">
                Projects map to saved workflows. Pick a workflow below or create a new one. Per-pane project tags are set when you add a chat pane.
            </p>
            <div className="flex items-center justify-between gap-2">
                <span className="text-[10px] uppercase tracking-[0.14em] text-slate-500 font-bold">
                    Active workflows ({rows.length})
                </span>
                {typeof onCreateSession === 'function' && (
                    <button
                        type="button"
                        data-testid="projects-mode-new-workflow"
                        onClick={onCreateSession}
                        className="px-3 py-1.5 rounded-lg border border-sky-400/30 bg-sky-500/10 text-[10px] font-mono uppercase tracking-[0.12em] text-sky-200 hover:bg-sky-500/20 transition-colors"
                    >
                        New workflow
                    </button>
                )}
            </motionList>
            <ul className="space-y-2 max-h-[min(60vh,480px)] overflow-y-auto pr-1">
                {rows.length === 0 && (
                    <li className="rounded-xl border border-dashed border-white/10 px-4 py-6 text-center text-[11px] font-mono text-slate-500">
                        No saved workflows yet.
                    </li>
                )}
                {rows.map((session) => {
                    const id = String(session?.id ?? session?.workflowId ?? '');
                    const label = String(session?.name ?? session?.label ?? id || 'Workflow');
                    const isActive = id && id === activeId;
                    return (
                        <li key={id || label}>
                            <button
                                type="button"
                                data-testid={`projects-mode-session-${id || 'unknown'}`}
                                onClick={() => {
                                    if (typeof onSelectSession === 'function' && id) {
                                        onSelectSession(id);
                                    }
                                }}
                                className={`w-full text-left rounded-xl border px-4 py-3 transition-colors ${
                                    isActive
                                        ? 'border-sky-400/40 bg-sky-500/10 text-sky-100'
                                        : 'border-white/10 bg-black/20 text-slate-200 hover:border-white/20 hover:bg-white/[0.04]'
                                }`}
                            >
                                <div className="text-[12px] font-semibold truncate">{label}</motionLabel>
                                <div className="text-[10px] font-mono text-slate-500 mt-0.5 truncate">{id || '—'}</div>
                            </button>
                        </li>
                    );
                })}
            </ul>
        </section>
    );
}

