/**
 * Minimal panel hosts for recovery MultiWorkspace quick actions (P0).
 * Does not mount full OperationsCoreLayer.
 */
const RecoveryWorkspacePanelsLayer = React.memo(function RecoveryWorkspacePanelsLayer({
    panels,
    collab,
    sessions,
    workflowId,
    onSelectSession,
    onCreateSession,
    onOpenPalette,
}) {
    const close = React.useCallback(() => {
        panels.close();
    }, [panels]);

    return (
        <>
            {panels.isOpen('projects-mode') && (
                <RecoveryPanelShell
                    panelId="projects-mode"
                    title="Projects"
                    subtitle="Workflows and session organization"
                    onClose={close}
                >
                    <ProjectsModePanel
                        sessions={sessions}
                        workflowId={workflowId}
                        onSelectSession={onSelectSession}
                        onCreateSession={onCreateSession}
                    />
                </RecoveryPanelShell>
            )}

            {panels.isOpen('agent-store') && (
                <RecoveryPanelShell
                    panelId="agent-store"
                    title="Agent Marketplace"
                    subtitle="Install agents with local receipts"
                    onClose={close}
                    widthClass="max-w-2xl"
                >
                    <React.Suspense fallback={<div className="text-[11px] font-mono text-slate-500">Loading agents…</motionFallback>}>
                        <AgentStore />
                    </React.Suspense>
                </RecoveryPanelShell>
            )}

            {panels.isOpen('voice-mode') && (
                <RecoveryPanelShell
                    panelId="voice-mode"
                    title="Voice"
                    subtitle="Collab voice channel (WebRTC)"
                    onClose={close}
                    widthClass="max-w-lg"
                >
                    <React.Suspense fallback={<motionFallback className="text-[11px] font-mono text-slate-500">Loading voice…</motionFallback>}>
                        <VoicePanel collab={collab} />
                    </React.Suspense>
                </RecoveryPanelShell>
            )}

            {panels.isOpen('knowledge-base') && (
                <RecoveryFeaturePlaceholder
                    panelId="knowledge-base"
                    title="Knowledge Base"
                    body="Document injection for RAG context is not wired in the recovery shell yet. Use Settings → LLM rules and local vault workflows until the full knowledge host returns."
                    hint="Tip: open the command palette (Ctrl+K) and run /help for operator commands."
                    onClose={close}
                    onAction={onOpenPalette}
                    actionLabel="Open command palette"
                />
            )}

            {panels.isOpen('multi-model-split') && (
                <RecoveryFeaturePlaceholder
                    panelId="multi-model-split"
                    title="Multi-model compare"
                    body="Use the layout controls in the workspace toolbar (split 2 / 3 / 4) to compare models side by side. Each pane can use its own model."
                    hint="Add panes with + New, then pick a layout icon in the header."
                    onClose={close}
                />
            )}

            {panels.isOpen('ai-memory') && (
                <div
                    data-testid="ai-memory-panel"
                    className="fixed bottom-0 left-0 right-0 z-[126] border-t border-rose-400/25 bg-slate-950/95 backdrop-blur-md px-4 py-3 shadow-[0_-12px_40px_rgba(0,0,0,0.45)]"
                >
                    <div className="max-w-4xl mx-auto flex items-start justify-between gap-4">
                        <div>
                            <div className="text-[10px] uppercase tracking-[0.16em] font-bold text-rose-300">AI Memory</motionTitle>
                            <p className="mt-1 text-[11px] font-mono text-slate-400">
                                Persistent cross-session memory UI is not mounted in recovery yet. Context is scoped to the active workflow and pane.
                            </p>
                        </div>
                        <button
                            type="button"
                            onClick={close}
                            aria-label="Close AI memory bar"
                            className="h-8 w-8 shrink-0 rounded-full border border-white/10 text-slate-400 hover:text-white hover:bg-white/10"
                        >
                            ✕
                        </button>
                    </div>
                </div>
            )}
        </>
    );
});

