/**
 * P0 proof: usePanelManager modal semantics (no React/Electron required).
 */
const assert = require('node:assert/strict');

function createPanelManager() {
    let activePanel = null;
    const pinnedSet = new Set();

    return {
        get activePanel() {
            return activePanel;
        },
        open(id) {
            activePanel = id;
        },
        close(id) {
            if (id) {
                if (activePanel === id) activePanel = null;
                pinnedSet.delete(id);
            } else {
                activePanel = null;
            }
        },
        toggle(id) {
            activePanel = activePanel === id ? null : id;
        },
        isOpen(id) {
            return activePanel === id || pinnedSet.has(id);
        },
        pin(id) {
            pinnedSet.add(id);
        },
    };
}

function run() {
    const pm = createPanelManager();
    pm.open('projects-mode');
    assert.equal(pm.isOpen('projects-mode'), true);
    assert.equal(pm.isOpen('agent-store'), false);

    pm.open('agent-store');
    assert.equal(pm.activePanel, 'agent-store');
    assert.equal(pm.isOpen('projects-mode'), false);

    pm.toggle('ai-memory');
    assert.equal(pm.isOpen('ai-memory'), true);
    pm.toggle('ai-memory');
    assert.equal(pm.isOpen('ai-memory'), false);

    pm.open('voice-mode');
    pm.close();
    assert.equal(pm.isOpen('voice-mode'), false);

    console.log('p0-panel-manager-proof: OK');
}

run();

/**
 * P0 manual signoff harness — Electron screenshots for recovery panel manager.
 * Output: validation-artifacts/post-release/phase-old-ui-parity-p0-panel-manager/screenshots/
 */
const { _electron: electron } = require('playwright');
const path = require('path');
const fs = require('fs');
const os = require('os');

const OUT_DIR = path.resolve(
    __dirname,
    '../validation-artifacts/post-release/phase-old-ui-parity-p0-panel-manager/screenshots',
);

const SHOTS = [
    { file: '01-projects-drawer.png', action: 'projects' },
    { file: '02-agents-drawer.png', action: 'agents' },
    { file: '03-voice-drawer.png', action: 'voice' },
    { file: '04-knowledge-base-placeholder.png', action: 'knowledge-base' },
    { file: '05-multi-model-guidance.png', action: 'multi-model' },
    { file: '06-ai-memory-bar.png', action: 'ai-memory' },
    { file: '07-command-palette.png', action: 'palette' },
    { file: '08-settings-drawer.png', action: 'settings' },
    { file: '09-help-response.png', action: 'help' },
    { file: '10-freeform-response.png', action: 'freeform' },
];

async function dismissOnboarding(page) {
    const close = page.getByTestId('onboarding-close-btn');
    if (await close.count()) {
        await close.first().click().catch(() => {});
        await page.waitForTimeout(150);
    }
}

async function closePanel(page) {
    const backdrop = page.locator('[data-testid^="recovery-panel-backdrop-"]');
    if (await backdrop.count()) {
        await backdrop.first().click({ force: true }).catch(() => {});
        await page.waitForTimeout(200);
    }
    const memoryClose = page.getByRole('button', { name: 'Close AI memory bar' });
    if (await memoryClose.count()) {
        await memoryClose.first().click().catch(() => {});
        await page.waitForTimeout(150);
    }
}

async function runAction(page, action) {
    await closePanel(page);

    if (action === 'projects') {
        await page.getByRole('button', { name: 'Projects (Ctrl+P)' }).click();
        await page.getByTestId('recovery-panel-projects-mode').waitFor({ timeout: 15000 });
        return;
    }
    if (action === 'agents') {
        await page.getByRole('button', { name: 'Agent Marketplace' }).click();
        await page.getByTestId('recovery-panel-agent-store').waitFor({ timeout: 15000 });
        return;
    }
    if (action === 'voice') {
        await page.getByRole('button', { name: 'Voice input' }).click();
        await page.getByTestId('recovery-panel-voice-mode').waitFor({ timeout: 15000 });
        return;
    }
    if (action === 'knowledge-base') {
        await page.getByRole('button', { name: 'Knowledge Base' }).click();
        await page.getByTestId('knowledge-base-panel').waitFor({ timeout: 15000 });
        return;
    }
    if (action === 'multi-model') {
        await page.getByRole('button', { name: 'Multi-model compare' }).click();
        await page.getByTestId('multi-model-split-panel').waitFor({ timeout: 15000 });
        return;
    }
    if (action === 'ai-memory') {
        await page.getByRole('button', { name: 'AI Memory' }).click();
        await page.getByTestId('ai-memory-panel').waitFor({ timeout: 15000 });
        return;
    }
    if (action === 'palette') {
        await page.getByTestId('command-palette-btn').click();
        await page.getByTestId('command-palette').waitFor({ timeout: 15000 });
        return;
    }
    if (action === 'settings') {
        await page.getByTestId('settings-open-btn').click();
        await page.getByTestId('settings-drawer').waitFor({ timeout: 15000 });
        return;
    }
    if (action === 'help') {
        await closePanel(page);
        const composer = page.getByTestId('chat-input').first();
        await composer.fill('/help');
        await page.getByRole('button', { name: 'Send' }).first().click();
        await page.getByText('NeuralShell Operator Guide').first().waitFor({ timeout: 60000 });
        return;
    }
    if (action === 'freeform') {
        await closePanel(page);
        const composer = page.getByTestId('chat-input').first();
        await composer.fill('Reply with exactly: P0_FREEFORM_OK');
        await page.getByRole('button', { name: 'Send' }).first().click();
        await page.getByText('P0_FREEFORM_OK').first().waitFor({ timeout: 90000 });
    }
}

async function main() {
    fs.mkdirSync(OUT_DIR, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-p0-signoff-'));
    const consoleErrors = [];
    const results = [];

    const app = await electron.launch({
        args: ['.'],
        cwd: path.resolve(__dirname, '..'),
        timeout: 120000,
        env: {
            ...process.env,
            NEURAL_USER_DATA_DIR: userDataDir,
            NEURAL_IGNORE_INTEGRITY: '1',
        },
    });

    const page = await app.firstWindow({ timeout: 120000 });
    page.on('console', (msg) => {
        if (msg.type() === 'error') {
            consoleErrors.push(msg.text());
        }
    });
    page.on('pageerror', (err) => {
        consoleErrors.push(String(err && err.message ? err.message : err));
    });

    await page.setViewportSize({ width: 1440, height: 900 });
    await page.waitForLoadState('domcontentloaded');
    await page.evaluate(() => {
        globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
    });
    await page.reload();
    await page.getByTestId('top-status-bar').waitFor({ timeout: 30000 });
    await page.locator('#main-workspace').waitFor({ timeout: 30000 });
    await dismissOnboarding(page);

    for (const shot of SHOTS) {
        const entry = { file: shot.file, action: shot.action, ok: false, error: '' };
        try {
            await runAction(page, shot.action);
            await page.waitForTimeout(300);
            await page.screenshot({ path: path.join(OUT_DIR, shot.file), fullPage: true });
            entry.ok = true;
        } catch (err) {
            entry.error = err && err.message ? err.message : String(err);
            await page.screenshot({
                path: path.join(OUT_DIR, shot.file.replace('.png', '-FAIL.png')),
                fullPage: true,
            }).catch(() => {});
        }
        results.push(entry);
        if (shot.action !== 'ai-memory' && shot.action !== 'help' && shot.action !== 'freeform') {
            await closePanel(page);
        }
    }

    await app.close();
    try {
        fs.rmSync(userDataDir, { recursive: true, force: true });
    } catch {
        // ignore
    }

    const summary = {
        capturedAt: new Date().toISOString(),
        outDir: OUT_DIR,
        results,
        consoleErrors: consoleErrors.filter((e) => !/devtools/i.test(e)),
    };
    fs.writeFileSync(
        path.join(OUT_DIR, 'signoff-results.json'),
        JSON.stringify(summary, null, 2),
        'utf8',
    );

    const failed = results.filter((r) => !r.ok);
    console.log(JSON.stringify(summary, null, 2));
    if (failed.length) {
        process.exitCode = 1;
    }
}

main().catch((err) => {
    console.error(err);
    process.exit(1);
});

