/**
 * HOTFIX-2134 provider proof (no Electron UI).
 *
 * Default CI: mandatory static/local checks only (role normalization + validator).
 * Live Ollama: auto-run when reachable on the host, or required when OLLAMA_INTEGRATION=1.
 * GitHub Actions runners typically have no Ollama at 127.0.0.1:11434 — that is expected.
 */
const assert = require('assert');
const { validateMessages } = require('../src/core/ipcValidators');
const { toProviderMessages } = require('../src/renderer/src/lib/toProviderMessages.js');
const { LLMService } = require('../src/core/llmService');

const ALLOWED_PROVIDER_ROLES = new Set(['system', 'user', 'assistant']);
const OLLAMA_BASE_URL = 'http://127.0.0.1:11434';

function expectReject(fn, re) {
    let threw = false;
    try {
        fn();
    } catch (err) {
        threw = true;
        assert.match(String(err.message || err), re);
    }
    assert.equal(threw, true, 'expected throw');
}

function integrationRequired() {
    const raw = String(process.env.OLLAMA_INTEGRATION || '').trim();
    return raw === '1' || raw.toLowerCase() === 'true';
}

/**
 * Mandatory static proof — must pass in CI and locally.
 * @returns {{ roles: string[], payload: object[] }}
 */
function runStaticProof() {
    const uiLog = [
        { role: 'kernel', content: '### NeuralShell Operator Guide\n- /help' },
        { role: 'user', content: 'say ok after help' },
    ];

    expectReject(() => validateMessages(uiLog), /invalid message role: kernel/i);

    const payload = toProviderMessages(uiLog);
    const roles = payload.map((m) => m.role);
    assert.deepEqual(roles, ['assistant', 'user'], 'kernel must map to assistant before user');
    for (const row of payload) {
        assert.ok(ALLOWED_PROVIDER_ROLES.has(row.role), `unexpected provider role: ${row.role}`);
        assert.ok(String(row.content || '').trim().length > 0, 'empty content must be filtered');
    }
    validateMessages(payload);

    const withEmpty = toProviderMessages([
        { role: 'kernel', content: '   ' },
        { role: 'user', content: 'hello' },
        { role: 'assistant', content: '' },
    ]);
    assert.deepEqual(
        withEmpty.map((m) => m.role),
        ['user'],
        'contentless rows must be dropped',
    );

    return { roles, payload };
}

/**
 * Optional live Ollama integration — skipped when unreachable unless OLLAMA_INTEGRATION=1.
 */
async function runOllamaIntegration(payload) {
    const svc = new LLMService({ baseUrl: OLLAMA_BASE_URL, provider: 'ollama' });
    svc.setModel('llama3');

    const health = await svc.getHealth();
    if (!health.ok) {
        const reason = health.reason || 'fetch failed';
        if (integrationRequired()) {
            const out = {
                pass: false,
                staticProof: 'pass',
                ollamaIntegration: 'failed',
                reason,
            };
            console.error(JSON.stringify(out));
            process.exit(1);
        }
        return {
            ollamaIntegration: 'skipped',
            reason: 'no ollama on runner',
            health,
        };
    }

    const direct = await svc.chat([{ role: 'user', content: 'say ok' }], false);
    const directText = String(direct?.message?.content || '');
    assert.ok(directText.length > 0, 'direct freeform empty');

    const afterHelp = await svc.chat(payload, false);
    const afterText = String(afterHelp?.message?.content || '');
    assert.ok(afterText.length > 0, 'after-help normalized empty');

    return {
        ollamaIntegration: 'pass',
        health,
        directSnippet: directText.slice(0, 120),
        afterHelpSnippet: afterText.slice(0, 120),
    };
}

