const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');
const { _electron: electron } = require('playwright');
const { execSync } = require('child_process');

const ROOT = path.resolve(__dirname, '../..');
const OUT_DIR = path.dirname(__filename);
const INSTALLED_EXE = path.join(
  process.env.LOCALAPPDATA || '',
  'Programs',
  'NeuralShell',
  'NeuralShell.exe',
);
const EXPECT_VERSION = '2.1.34';
const EXPECT_BUNDLE = 'index-Cz8DcPWE.js';

const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

function sha256(filePath) {
  const hash = crypto.createHash('sha256');
  hash.update(fs.readFileSync(filePath));
  return hash.digest('hex');
}

function readRegistryVersion() {
  try {
    const raw = execSync(
      'reg query "HKCU\\Software\\NeuralShell" /v Version',
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] },
    );
    const match = /Version\s+REG_SZ\s+(.+)/i.exec(raw);
    return match ? String(match[1]).trim() : '';
  } catch {
    return '';
  }
}

async function waitVisible(page, selector, timeout = 30000) {
  await page.locator(selector).first().waitFor({ state: 'visible', timeout });
}

async function dismissOnboarding(page) {
  const close = page.getByTestId('onboarding-close-btn');
  if (await close.count()) {
    await close.first().click().catch(() => {});
    await page.waitForTimeout(150);
  }
  await page.evaluate(() => {
    try {
      globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
    } catch {
      // ignore
    }
  });
}

async function sendCommand(page, command, waitMs = 1200) {
  await page.getByTestId('chat-input').fill(command);
  await page.getByRole('button', { name: 'Execute Command' }).click();
  await page.waitForTimeout(waitMs);
}

async function chatRows(page) {
  return page.locator('[data-testid="chat-message"]').allTextContents();
}

function classifyOllama(consoleLines, chatText) {
  const blob = `${consoleLines.join('\n')}\n${chatText}`;
  if (/invalid message role:\s*kernel/i.test(blob)) {
    return { classification: 'kernel_role_error', ok: false };
  }
  if (/EACCES|listen EADDRINUSE|port.*crash/i.test(blob)) {
    return { classification: 'port_crash', ok: false };
  }
  if (/ollama.*(offline|unavailable|not running|connection refused|fetch failed)/i.test(blob)) {
    return { classification: 'ollama_missing_or_offline', ok: true, note: 'clear setup/connection messaging' };
  }
  if (/ollama.*(online|ready|connected)/i.test(blob) || /model.*available/i.test(blob)) {
    return { classification: 'ollama_reachable', ok: true };
  }
  if (/assistant|reply|response/i.test(chatText) && !/error/i.test(chatText)) {
    return { classification: 'direct_chat_response', ok: true };
  }
  return { classification: 'unclassified', ok: true, note: 'no hard failure detected' };
}

async function main() {
  fs.mkdirSync(OUT_DIR, { recursive: true });

  if (!fs.existsSync(INSTALLED_EXE)) {
    throw new Error(`Installed exe missing: ${INSTALLED_EXE}`);
  }

  const asarPath = path.join(path.dirname(INSTALLED_EXE), 'resources', 'app.asar');
  const report = {
    stamp,
    installedExe: INSTALLED_EXE,
    registryVersion: readRegistryVersion(),
    expectVersion: EXPECT_VERSION,
    expectBundle: EXPECT_BUNDLE,
    checks: {},
    consoleErrors: [],
    pageErrors: [],
    screenshots: {},
    pass: false,
  };

  const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-2134-proof-'));
  const consoleAll = [];
  const pageErrors = [];
  let app = null;

  try {
    app = await electron.launch({
      executablePath: INSTALLED_EXE,
      args: [],
      timeout: 120000,
      env: {
        ...process.env,
        NEURAL_USER_DATA_DIR: userDataDir,
        NEURAL_IGNORE_INTEGRITY: '1',
      },
    });

    const page = await app.firstWindow({ timeout: 120000 });
    await page.setViewportSize({ width: 1440, height: 900 });

    page.on('console', (msg) => {
      const line = `[${msg.type()}] ${msg.text()}`;
      consoleAll.push(line);
      if (msg.type() === 'error') report.consoleErrors.push(line);
    });
    page.on('pageerror', (err) => {
      const line = String(err && err.stack ? err.stack : err);
      pageErrors.push(line);
      report.pageErrors.push(line);
    });

    await page.waitForLoadState('domcontentloaded');
    await dismissOnboarding(page);
    await page.reload();
    await waitVisible(page, '[data-testid="top-status-bar"]');
    await waitVisible(page, '[data-testid="workspace-panel"]');

    const shellShot = path.join(OUT_DIR, `${stamp}-01-initial-shell.png`);
    await page.screenshot({ path: shellShot, fullPage: true });
    report.screenshots.initialShell = shellShot;
    report.checks.initialRecoveredShell = {
      topStatusBar: true,
      workspacePanel: await page.locator('[data-testid="workspace-panel"]').isVisible(),
      threadRail: await page.locator('[data-testid="thread-rail"]').isVisible(),
    };

    await sendCommand(page, 'package proof: direct freeform before help', 2500);
    const beforeHelpRows = await chatRows(page);
    const beforeHelpShot = path.join(OUT_DIR, `${stamp}-02-freeform-before-help.png`);
    await page.screenshot({ path: beforeHelpShot, fullPage: true });
    report.screenshots.freeformBeforeHelp = beforeHelpShot;
    const kernelBefore = /invalid message role:\s*kernel/i.test(beforeHelpRows.join('\n'));
    report.checks.freeformBeforeHelp = {
      sent: true,
      kernelRoleError: kernelBefore,
      sampleRows: beforeHelpRows.slice(-6),
    };

    await sendCommand(page, '/help', 1800);
    const helpRows = await chatRows(page);
    const helpOk = helpRows.some((row) => /NeuralShell Operator Guide/i.test(row));
    const helpShot = path.join(OUT_DIR, `${stamp}-03-after-help.png`);
    await page.screenshot({ path: helpShot, fullPage: true });
    report.screenshots.afterHelp = helpShot;
    report.checks.helpOperatorGuide = {
      pass: helpOk,
      sampleRows: helpRows.slice(-8),
    };

    await sendCommand(page, 'package proof: freeform after help — ollama path', 4500);
    const afterHelpRows = await chatRows(page);
    const afterHelpShot = path.join(OUT_DIR, `${stamp}-04-freeform-after-help.png`);
    await page.screenshot({ path: afterHelpShot, fullPage: true });
    report.screenshots.freeformAfterHelp = afterHelpShot;
    const kernelAfter = /invalid message role:\s*kernel/i.test(
      `${afterHelpRows.join('\n')}\n${consoleAll.join('\n')}`,
    );
    report.checks.freeformAfterHelp = {
      sent: true,
      kernelRoleError: kernelAfter,
      sampleRows: afterHelpRows.slice(-10),
    };
    report.checks.kernelRoleErrorPresent = kernelBefore || kernelAfter;

    report.checks.ollama = classifyOllama(consoleAll, afterHelpRows.join('\n'));

    const settingsBtn = page.getByTestId('settings-open-btn');
    await settingsBtn.click();
    await waitVisible(page, '[data-testid="settings-drawer"]', 10000);
    const settingsShot = path.join(OUT_DIR, `${stamp}-05-settings-drawer.png`);
    await page.screenshot({ path: settingsShot, fullPage: true });
    report.screenshots.settingsDrawer = settingsShot;
    report.checks.settingsDrawer = { pass: true };
    await page.getByTestId('settings-close-btn').click().catch(() => {});
    await page.waitForTimeout(200);

    await page.keyboard.press('Control+K');
    await waitVisible(page, '[data-testid="command-palette"]', 10000);
    const paletteShot = path.join(OUT_DIR, `${stamp}-06-command-palette.png`);
    await page.screenshot({ path: paletteShot, fullPage: true });
    report.screenshots.commandPalette = paletteShot;
    report.checks.commandPalette = { pass: true, shortcut: 'Ctrl+K' };
    await page.keyboard.press('Escape');
    await page.waitForTimeout(200);

    const layoutIds = ['hud', 'dense', 'standard', 'spacious'];
    const layoutResults = {};
    for (const id of layoutIds) {
      const btn = page.getByTestId(`layout-preset-${id}-btn`);
      if (await btn.isVisible().catch(() => false)) {
        await btn.click().catch(() => {});
        layoutResults[id] = true;
        await page.waitForTimeout(120);
      } else {
        layoutResults[id] = false;
      }
    }
    const layoutShot = path.join(OUT_DIR, `${stamp}-07-layout-presets.png`);
    await page.screenshot({ path: layoutShot, fullPage: true });
    report.screenshots.layoutPresets = layoutShot;
    report.checks.layoutPresets = layoutResults;

    report.checks.reactPageErrors = report.pageErrors.length === 0;
    report.checks.unexpectedConsoleErrors = report.consoleErrors.filter(
      (line) => !/devtools|favicon|ResizeObserver|Electron Security Warning/i.test(line),
    );

    if (fs.existsSync(asarPath)) {
      const asarBuf = fs.readFileSync(asarPath);
      report.installedAsar = {
        path: asarPath,
        size: asarBuf.length,
        sha256: crypto.createHash('sha256').update(asarBuf).digest('hex'),
        containsValidationArtifacts: asarBuf.includes(Buffer.from('validation-artifacts')),
      };
      const indexHtml = path.join(path.dirname(INSTALLED_EXE), 'resources', 'app.asar.unpacked');
      // bundle name from dist inside asar — search buffer for index-*.js
      const bundleMatch = asarBuf.toString('latin1').match(/index-[A-Za-z0-9_-]+\.js/g);
      report.activeRendererBundles = bundleMatch ? [...new Set(bundleMatch)].slice(0, 20) : [];
    }

    report.pass =
      report.registryVersion === EXPECT_VERSION &&
      report.checks.helpOperatorGuide.pass &&
      !report.checks.kernelRoleErrorPresent &&
      report.checks.initialRecoveredShell.topStatusBar &&
      report.checks.settingsDrawer.pass &&
      report.checks.commandPalette.pass &&
      Object.values(report.checks.layoutPresets).some(Boolean) &&
      report.checks.reactPageErrors &&
      report.checks.unexpectedConsoleErrors.length === 0 &&
      (!report.installedAsar || report.installedAsar.containsValidationArtifacts === false);
  } finally {
    if (app) await app.close().catch(() => {});
    try {
      fs.rmSync(userDataDir, { recursive: true, force: true });
    } catch {
      // ignore
    }
  }

  const reportPath = path.join(OUT_DIR, 'package-proof-report.json');
  fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
  console.log(JSON.stringify(report, null, 2));
  if (!report.pass) process.exitCode = 1;
}

main().catch((err) => {
  console.error(err && err.stack ? err.stack : err);
  process.exitCode = 1;
});

