  const started = Date.now();
  return new Promise((resolve, reject) => {
    const tick = () => {
      const socket = new net.Socket();
      socket.setTimeout(800);
      socket
        .once('connect', () => {
          socket.destroy();
          resolve(true);
        })
        .once('timeout', () => {
          socket.destroy();
          retry();
        })
        .once('error', () => {
          socket.destroy();
          retry();
        });
      socket.connect(port, '127.0.0.1');
    };
    const retry = () => {
      if (Date.now() - started > timeoutMs) {
        reject(new Error(`Timed out waiting for debug port ${port}`));
        return;
      }
      setTimeout(tick, 350);
    };
    tick();
  });
}

