const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawn } = require('child_process');
const { chromium } = require('playwright');

const OUT = __dirname;
const EXE = path.join(process.env.LOCALAPPDATA || '', 'Programs', 'NeuralShell', 'NeuralShell.exe');
const DEBUG_PORT = 9222;
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

async function waitCdp(port, ms = 120000) {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/version`);
      if (res.ok) return;
    } catch {
      // retry
    }
    await new Promise((r) => setTimeout(r, 400));
  }
  throw new Error(`CDP not ready on ${port}`);
}

async function dismiss(page) {
  for (const sel of ['[data-testid="onboarding-close-btn"]', 'button:has-text("Continue")', 'button:has-text("Skip")']) {
    const el = page.locator(sel).first();
    if (await el.isVisible().catch(() => false)) await el.click({ force: true }).catch(() => {});
  }
  await page.keyboard.press('Escape').catch(() => {});
}

async function send(page, text, wait = 2000) {
  await dismiss(page);
  const input = page.getByTestId('chat-input').first();
  await input.fill(text);
  const sendBtn = page.getByRole('button', { name: 'Send' });
  if (await sendBtn.isVisible().catch(() => false)) await sendBtn.click({ force: true });
  else await page.getByRole('button', { name: 'Execute Command' }).click({ force: true }).catch(() => input.press('Enter'));
  await page.waitForTimeout(wait);
}

async function panelText(page) {
  return page.locator('[data-testid="workspace-panel"]').innerText();
}

async function main() {
  const userData = fs.mkdtempSync(path.join(os.tmpdir(), 'ns-2134-final-'));
  const logs = [];
  const report = { stamp, pass: false, checks: {}, consoleErrors: [], pageErrors: [] };
  let child;
  let browser;

  try {
    child = spawn(EXE, [`--remote-debugging-port=${DEBUG_PORT}`], {
      env: { ...process.env, NEURAL_USER_DATA_DIR: userData, NEURAL_IGNORE_INTEGRITY: '1', CI: '1' },
      stdio: 'ignore',
      windowsHide: false,
    });
    await waitCdp(DEBUG_PORT);
    browser = await chromium.connectOverCDP(`http://127.0.0.1:${DEBUG_PORT}`, { timeout: 120000 });
    const ctx = browser.contexts()[0];
    const page = ctx.pages()[0] || (await ctx.waitForEvent('page', { timeout: 60000 }));

    page.on('console', (m) => {
      const line = `[${m.type()}] ${m.text()}`;
      logs.push(line);
      if (m.type() === 'error') report.consoleErrors.push(line);
    });
    page.on('pageerror', (e) => report.pageErrors.push(String(e));

    await page.waitForLoadState('domcontentloaded');
    await page.waitForTimeout(2500);
    await dismiss(page);
    await page.evaluate(() => {
      try { localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1'); } catch {}
    });
    await page.waitForSelector('[data-testid="top-status-bar"]', { timeout: 90000 });

    await page.screenshot({ path: path.join(OUT, `${stamp}-01-shell.png`) });
    report.checks.initialRecoveredShell = true;

    await send(page, 'package proof before help', 3000);
    const t1 = await panelText(page);
    report.checks.freeformBeforeHelp = {
      kernelError: /invalid message role:\s*kernel/i.test(`${t1}\n${logs.join('\n')}`),
      hasUserText: t1.includes('package proof before help'),
    };
    await page.screenshot({ path: path.join(OUT, `${stamp}-02-before-help.png`) });

    await send(page, '/help', 5000);
    const t2 = await panelText(page);
    report.checks.helpOperatorGuide = {
      pass: /NeuralShell Operator Guide/i.test(t2),
      snippet: t2.slice(0, 500),
    };
    await page.screenshot({ path: path.join(OUT, `${stamp}-03-help.png`) });

    await send(page, 'package proof after help', 6000);
    const t3 = await panelText(page);
    const blob = `${t3}\n${logs.join('\n')}`;
    report.checks.freeformAfterHelp = {
      kernelError: /invalid message role:\s*kernel/i.test(blob),
      eacces: /EACCES/i.test(blob),
    };
    report.checks.kernelRoleErrorPresent = report.checks.freeformBeforeHelp.kernelError || report.checks.freeformAfterHelp.kernelError;
    report.checks.ollama = (() => {
      if (/invalid message role:\s*kernel/i.test(blob)) return { classification: 'kernel_role_error', ok: false };
      if (/EACCES/i.test(blob)) return { classification: 'port_crash', ok: false };
      if (/ollama|fetch failed|connection refused|not running/i.test(blob)) return { classification: 'ollama_missing_or_offline', ok: true };
      if (/assistant|reply/i.test(t3)) return { classification: 'direct_chat_response', ok: true };
      return { classification: 'unclassified', ok: true };
    })();
    await page.screenshot({ path: path.join(OUT, `${stamp}-04-after-help.png`) });

    await page.getByTestId('settings-open-btn').click();
    await page.waitForSelector('[data-testid="settings-drawer"]', { timeout: 15000 });
    report.checks.settingsDrawer = true;
    await page.screenshot({ path: path.join(OUT, `${stamp}-05-settings.png`) });
    await page.getByTestId('settings-close-btn').click().catch(() => {});

    await page.getByTestId('command-palette-btn').click({ force: true });
    await page.waitForSelector('[data-testid="command-palette"]', { timeout: 15000 });
    report.checks.commandPalette = true;
    await page.screenshot({ path: path.join(OUT, `${stamp}-06-palette.png`) });
    await page.keyboard.press('Escape');

    const layouts = {};
    for (const id of ['hud', 'dense', 'standard', 'spacious']) {
      const b = page.getByTestId(`layout-preset-${id}-btn`);
      layouts[id] = await b.isVisible().catch(() => false);
      if (layouts[id]) await b.click().catch(() => {});
    }
    report.checks.layoutPresets = layouts;
    await page.screenshot({ path: path.join(OUT, `${stamp}-07-layouts.png`) });

    report.checks.reactPageErrors = report.pageErrors.length === 0;
    report.checks.filteredConsoleErrors = report.consoleErrors.filter(
      (l) => !/Electron Security Warning|devtools|favicon|ResizeObserver/i.test(l),
    );

    report.pass =
      report.checks.initialRecoveredShell &&
      report.checks.helpOperatorGuide.pass &&
      !report.checks.kernelRoleErrorPresent &&
      !report.checks.freeformAfterHelp.eacces &&
      report.checks.settingsDrawer &&
      report.checks.commandPalette;
  } finally {
    if (browser) await browser.close().catch(() => {});
    if (child && !child.killed) child.kill();
    fs.rmSync(userData, { recursive: true, force: true });
    fs.writeFileSync(path.join(OUT, 'package-proof-report.json'), JSON.stringify(report, null, 2));
    console.log(JSON.stringify(report, null, 2));
  }
  if (!report.pass) process.exitCode = 1;
}

main().catch((e) => { console.error(e); process.exitCode = 1; });

