const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawn, execSync } = require('child_process');
const { chromium } = require('playwright');

const OUT = __dirname;
const EXE = path.join(process.env.LOCALAPPDATA || '', 'Programs', 'NeuralShell', 'NeuralShell.exe');
const ASAR = path.join(path.dirname(EXE), 'resources', 'app.asar');
const EXPECT_ASAR_SHA = '274d13dca5cbb31f9f98a3bce819dbed15984ab61c9e1b5e9f53c4b8a10676b9';
const EXPECT_BUNDLE = 'index-Cz8DcPWE.js';
const CDP_PORT = 9222;
const OPERATOR_GUIDE = 'NeuralShell Operator Guide';
const NODECHAIN_STALE = /NodeChain prompted a vault save/i;

function sha256(filePath) {
  const crypto = require('crypto');
  return crypto.createHash('sha256').update(fs.readFileSync(filePath)).digest('hex');
}

function readRegistryVersion() {
  try {
    const raw = execSync('reg query "HKCU\\Software\\NeuralShell" /v Version', { encoding: 'utf8' });
    const m = /Version\s+REG_SZ\s+(.+)/i.exec(raw);
    return m ? String(m[1]).trim() : '';
  } catch {
    return '';
  }
}

function killNeuralShell() {
  try {
    execSync('powershell -NoProfile -Command "Get-Process NeuralShell -ErrorAction SilentlyContinue | Stop-Process -Force"', {
      stdio: 'ignore',
    });
  } catch {
    // ignore
  }
}

function freePort(port) {
  try {
    execSync(
      `powershell -NoProfile -Command "Get-NetTCPConnection -LocalPort ${port} -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id $_.OwningProcess -Force -ErrorAction SilentlyContinue }"`,
      { stdio: 'ignore' },
    );
  } catch {
    // ignore
  }
}

async function waitCdp(port, ms = 90000) {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/version`);
      if (res.ok) return;
    } catch {
      // retry
    }
    await new Promise((r) => setTimeout(r, 300));
  }
  throw new Error(`CDP not ready on port ${port}`);
}

async function dismissOverlays(page) {
  const selectors = [
    '[data-testid="onboarding-close-btn"]',
    '[data-testid="success-capture-close-btn"]',
    'button:has-text("Continue")',
    'button:has-text("Get Started")',
    'button:has-text("Skip")',
    'button:has-text("Close")',
    'button:has-text("Dismiss")',
  ];
  for (let round = 0; round < 5; round += 1) {
    for (const sel of selectors) {
      const el = page.locator(sel).first();
      if (await el.isVisible().catch(() => false)) {
        await el.click({ force: true, timeout: 1500 }).catch(() => {});
        await page.waitForTimeout(100);
      }
