    await page.getByRole('button', { name: 'Execute Command' }).click({ force: true }).catch(() => input.press('Enter'));
  }
}

async function waitForOperatorGuide(page, maxMs = 1500) {
  const end = Date.now() + maxMs;
  while (Date.now() < end) {
    const text = await panelText(page);
    if (text.includes(OPERATOR_GUIDE)) {
      return { found: true, text, staleNodeChainOnly: false };
    }
    await page.waitForTimeout(80);
  }
  const text = await panelText(page);
  const hasGuide = text.includes(OPERATOR_GUIDE);
  const staleOnly = NODECHAIN_STALE.test(text) && !hasGuide;
  return { found: hasGuide, text, staleNodeChainOnly: staleOnly };
}

function classifyFreeform(text, logs) {
  const blob = `${text}\n${logs.join('\n')}`;
  if (/invalid message role:\s*kernel/i.test(blob)) {
    return { pass: false, reason: 'kernel_role_error' };
  }
  if (/Kernel Error/i.test(blob)) {
    return { pass: false, reason: 'kernel_error_banner' };
  }
  if (/EACCES/i.test(blob)) {
    return { pass: false, reason: 'eacces' };
  }
  if (/ollama|fetch failed|connection refused|not running|setup|configure.*model/i.test(blob)) {
    return { pass: true, reason: 'clear_setup_or_connection' };
  }
  if (/\bok\b|assistant|reply|response/i.test(blob) && !/Kernel Error/i.test(blob)) {
    return { pass: true, reason: 'provider_response' };
  }
  return { pass: true, reason: 'no_hard_failure' };
}

function classifyOllama(text, logs) {
  const blob = `${text}\n${logs.join('\n')}`;
  if (/invalid message role:\s*kernel/i.test(blob)) return 'kernel_role_error';
  try {
    const health = execSync('curl -s -m 2 http://127.0.0.1:11434/api/tags', { encoding: 'utf8' });
    if (health && health.includes('models')) {
      if (/fetch failed|connection refused|not running|offline/i.test(blob)) {
        return 'ollama_running_but_app_reports_issue';
      }
      return 'ollama_running';
    }
  } catch {
    // not running
  }
  if (/ollama|fetch failed|connection|setup|configure/i.test(blob)) {
    return 'ollama_not_running_clear_message';
  }
  return 'ollama_status_unknown';
}

