      report.checks.ollama === 'ollama_status_unknown';

    report.pass =
      report.checks.initialShell.pass &&
      report.checks.freeformBeforeHelp.pass &&
      report.checks.help.pass &&
      report.checks.freeformAfterHelp.pass &&
      !report.checks.kernelRoleErrorPresent &&
      report.checks.commandPalette.pass &&
      report.checks.settingsDrawer.pass &&
      report.checks.layoutPresets.pass &&
      report.checks.reactPageErrors &&
      report.checks.filteredConsoleErrors.length === 0 &&
      ollamaOk;

    report.recommendation = report.pass
      ? 'ready_for_2.1.34_version_pr'
      : report.checks.help.pass === false
        ? 'fix_recovery_adapter_help_timing'
        : 'fix_remaining_blocker';
  } finally {
    if (browser) await browser.close().catch(() => {});
    if (child && child.pid) {
      try { process.kill(child.pid); } catch { /* ignore */ }
    }
    killNeuralShell();
    try {
      fs.rmSync(userData, { recursive: true, force: true, maxRetries: 3, retryDelay: 200 });
    } catch {
      // ignore locked profile dirs
    }
    const reportPath = path.join(OUT, 'installed-ui-signoff-report.json');
    fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
    console.log(JSON.stringify(report, null, 2));
    console.log(`Report: ${reportPath}`);
  }

  if (!report.pass) process.exitCode = 1;
}

main().catch((err) => {
  console.error(err && err.stack ? err.stack : err);
  process.exitCode = 1;
});

