const fs = require('fs');
const os = require('os');
const path = require('path');
const { execSync } = require('child_process');
const { _electron: electron } = require('playwright');

const OUT = __dirname;
const EXE = path.join(process.env.LOCALAPPDATA || '', 'Programs', 'NeuralShell', 'NeuralShell.exe');

async function dismiss(page) {
  await page.keyboard.press('Escape').catch(() => {});
  const close = page.getByTestId('onboarding-close-btn');
  if (await close.isVisible().catch(() => false)) await close.click({ force: true }).catch(() => {});
}

async function main() {
  execSync('powershell -NoProfile -Command "Get-Process NeuralShell -EA SilentlyContinue | Stop-Process -Force"', { stdio: 'ignore' });
  await new Promise((r) => setTimeout(r, 2000));
  const userData = fs.mkdtempSync(path.join(os.tmpdir(), 'ns-tail-'));
  const result = { pass: false, checks: {} };
  let app;
  try {
    app = await electron.launch({
      executablePath: EXE,
      ignoreDefaultArgs: true,
      timeout: 120000,
      env: { ...process.env, NEURAL_USER_DATA_DIR: userData, NEURAL_IGNORE_INTEGRITY: '1', CI: '1' },
    });
    const page = await app.firstWindow({ timeout: 120000 });
    page.setDefaultTimeout(10000);
    await page.waitForSelector('[data-testid="top-status-bar"]', { timeout: 60000 });
    await dismiss(page);

    await page.getByTestId('command-palette-btn').click({ force: true, noWaitAfter: true });
    await page.waitForSelector('[data-testid="command-palette"]', { timeout: 10000 });
    result.checks.commandPalette = true;
    await page.screenshot({ path: path.join(OUT, '05-command-palette.png'), timeout: 8000 }).catch(() => {});
    await page.keyboard.press('Escape');

    await page.getByTestId('settings-open-btn').click({ force: true, noWaitAfter: true });
    await page.waitForSelector('[data-testid="settings-drawer"]', { timeout: 10000 });
    result.checks.settingsDrawer = true;
    await page.screenshot({ path: path.join(OUT, '06-settings-drawer.png'), timeout: 8000 }).catch(() => {});
    await page.getByTestId('settings-close-btn').click().catch(() => {});

    const layouts = {};
    for (const id of ['hud', 'dense', 'standard', 'spacious']) {
      const btn = page.getByTestId(`layout-preset-${id}-btn`);
      layouts[id] = (await btn.count()) > 0;
      if (layouts[id]) await btn.click({ force: true, noWaitAfter: true }).catch(() => {});
    }
    result.checks.layoutPresets = layouts;
    result.checks.layoutPass = Object.values(layouts).every(Boolean);
    await page.screenshot({ path: path.join(OUT, '07-layout-presets.png'), timeout: 8000 }).catch(() => {});

    result.pass = result.checks.commandPalette && result.checks.settingsDrawer && result.checks.layoutPass;
  } finally {
    if (app) await app.close().catch(() => {});
    execSync('powershell -NoProfile -Command "Get-Process NeuralShell -EA SilentlyContinue | Stop-Process -Force"', { stdio: 'ignore' });
    fs.rmSync(userData, { recursive: true, force: true });
    fs.writeFileSync(path.join(OUT, 'tail-ui-signoff-report.json'), JSON.stringify(result, null, 2));
    console.log(JSON.stringify(result, null, 2));
  }
  process.exitCode = result.pass ? 0 : 1;
}

main().catch((e) => { console.error(e); process.exit(1); });

