const { _electron: electron } = require('playwright');

const OUT = __dirname;
const EXE = path.join(process.env.LOCALAPPDATA || '', 'Programs', 'NeuralShell', 'NeuralShell.exe');
const GUIDE = 'NeuralShell Operator Guide';

async function dismiss(page) {
  await page.keyboard.press('Escape').catch(() => {});
  for (const sel of ['[data-testid="onboarding-close-btn"]', 'button:has-text("Skip")', 'button:has-text("Continue")']) {
    const el = page.locator(sel).first();
    if (await el.isVisible().catch(() => false)) await el.click({ force: true }).catch(() => {});
  }
}

async function send(page, text) {
  await dismiss(page);
  const input = page.getByTestId('chat-input').first();
  await input.fill(text, { force: true });
  const send = page.getByRole('button', { name: 'Send' });
  await send.click({ force: true, noWaitAfter: true });
}

async function chat(page) {
  return (await page.locator('[data-testid="chat-message"]').allTextContents({ timeout: 8000 })).join('\n');
}

async function main() {
  const userData = fs.mkdtempSync(path.join(os.tmpdir(), 'ns-chat-signoff-'));
  const logs = [];
  const report = { pass: false, checks: {} };
  let app;
  try {
    app = await electron.launch({
      executablePath: EXE,
      ignoreDefaultArgs: true,
      timeout: 120000,
      env: { ...process.env, NEURAL_USER_DATA_DIR: userData, NEURAL_IGNORE_INTEGRITY: '1', CI: '1' },
    });
    const page = await app.firstWindow({ timeout: 120000 });
    page.on('console', (m) => logs.push(`[${m.type()}] ${m.text()}`));
    await page.waitForSelector('[data-testid="workspace-panel"]', { timeout: 60000 });
    await dismiss(page);

    await send(page, 'say ok before help');
    await page.waitForTimeout(4000);
    const t1 = await chat(page);
    report.checks.beforeHelp = {
      pass: !/invalid message role:\s*kernel|Kernel Error|EACCES/i.test(`${t1}\n${logs}`),
      sample: t1.slice(-300),
    };
    await page.screenshot({ path: path.join(OUT, '02-before-help-freeform.png'), timeout: 8000 }).catch(() => {});

    await send(page, '/help');
    let t2 = '';
    for (let i = 0; i < 40; i++) {
      t2 = await chat(page);
      if (t2.includes(GUIDE)) break;
      await page.waitForTimeout(100);
    }
    report.checks.help = {
      pass: t2.includes(GUIDE) && !(/NodeChain prompted a vault save/i.test(t2) && !t2.includes(GUIDE)),
      operatorGuideDetected: t2.includes(GUIDE),
      staleNodeChainOnly: /NodeChain prompted a vault save/i.test(t2) && !t2.includes(GUIDE),
      sample: t2.slice(-500),
    };
    await page.screenshot({ path: path.join(OUT, '03-help-operator-guide.png'), timeout: 8000 }).catch(() => {});

    await send(page, 'say ok after help');
    await page.waitForTimeout(5000);
    const t3 = await chat(page);
    report.checks.afterHelp = {
      pass: !/invalid message role:\s*kernel|Kernel Error|EACCES/i.test(`${t3}\n${logs}`),
      sample: t3.slice(-400),
    };
    report.checks.kernelRoleError = /invalid message role:\s*kernel/i.test(`${t1}\n${t3}\n${logs}`);
    await page.screenshot({ path: path.join(OUT, '04-after-help-freeform.png'), timeout: 8000 }).catch(() => {});

    report.pass = report.checks.beforeHelp.pass && report.checks.help.pass && report.checks.afterHelp.pass && !report.checks.kernelRoleError;
  } finally {
    if (app) await app.close().catch(() => {});
    fs.rmSync(userData, { recursive: true, force: true });
    fs.writeFileSync(path.join(OUT, 'chat-ui-signoff-report.json'), JSON.stringify(report, null, 2));
    console.log(JSON.stringify(report, null, 2));
  }
  process.exitCode = report.pass ? 0 : 1;
}

main().catch((e) => { console.error(e); process.exit(1); });

